   -------------------------------------------------------------------------- */
.developmentProcess {
  padding: 60px 0;
  text-align: center;
}
.developmentProcess .content {
  padding-bottom: 60px;
}
.developmentProcess .content h5 {
  font-size: 14px;
  font-weight: 600;
  color: #ec1c24;
  text-transform: uppercase;
  letter-spacing: 2px;
}
.developmentProcess .content h3 {
  font-size: 28px;
  font-weight: bold;
  color: #000;
}
.developmentProcess .content p {
  font-size: 16px;
  font-weight: 500;
  color: #000;
}
.developmentProcess .dev-slider {
  position: relative;
}
.developmentProcess .dev-slider .swiper-slide {
  height: auto !important;
}
.developmentProcess .testi-slider,
.testi-slider {
  position: unset !important;
}
.developmentProcess .swiper {
  overflow: hidden;
  padding: 10px;
}
.developmentProcess .swiper-slide {
  height: auto;
  display: flex;
}
.cyberSlider .swiper-wrapper {
  justify-content: center;
}
.dev-process .swiper-wrapper {
  align-items: center;
}
.testi-slider .swiper-pagination {
  display: none;
  bottom: -40px !important;
}
.dev-process .swiper-pagination {
  margin-top: 10px;
  position: relative !important;
  bottom: 0 !important;
}
.developmentProcess .dev-box {
  padding: 15px 20px;
  box-shadow: 0 3px 6px rgba(0, 0, 0, 0.16);
  border-radius: 10px;
  height: 300px;
  width: 100%;
  background: #fff;
  text-align: center;
}
.developmentProcess .dev-box img {
  margin-bottom: 10px;
  height: auto;
  max-width: 60px;
}
.developmentProcess .dev-box h2 {
  position: relative;
  font-size: 60px;
  font-weight: 800;
  color: #e5e5e5;
  top: -20px;
  left: -15px;
  text-align: left;
  margin: 0;
}
.developmentProcess .dev-box h3 {
  font-size: 20px;
  font-weight: bold;
  color: #000;
  transition: color 0.3s;
}
.box-left-align-featured .dev-box h3{
	text-align:left;
	
}
.box-left-align-featured .dev-box h3 span{
	position:unset;
}
.developmentProcess .dev-box h3 span {
  color: #ec1c24;
  font-size: 13px;
  font-weight: 400;
}
.developmentProcess .dev-box p {
  font-size: 16px;
  overflow: auto;
  height: 120px;
  padding: 0 6px;
}

.developmentProcess .dev-box p a{
	text-decoration:underline !important;
	color: #404040;
}
.developmentProcess .dev-box p::-webkit-scrollbar-track {
  -webkit-box-shadow: inset 0 0 6px rgba(0, 0, 0, 0.3);
  border-radius: 10px;
  background-color: #f5f5f5;
}
.developmentProcess .dev-box p::-webkit-scrollbar {
  width: 6px;
  background-color: #f5f5f5;
}
.developmentProcess .dev-box p::-webkit-scrollbar-thumb {
  border-radius: 10px;
  -webkit-box-shadow: inset 0 0 6px rgba(0, 0, 0, 0.3);
  background-color: #ec1c24;
}
.developmentProcess .dev-box:hover h4 {
  color: #ec1c24;
}
.developmentProcess .dev-box:hover img {
  filter: invert(24%) sepia(81%) saturate(2598%) hue-rotate(341deg)
    brightness(93%) contrast(100%);
}

/* Nav arrows â€” absolute outside swiper, matches live site */
.testimo-button-prev {
  position: absolute;
  left: -60px;
  top: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  cursor: pointer;
  z-index: 10;
  user-select: none;
}
.testimo-button-next {
  position: absolute;
  right: -60px;
  top: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  cursor: pointer;
  z-index: 10;
  user-select: none;
}
.testimo-button-prev svg,
.testimo-button-next svg {
  color: #bcbcbc;
  cursor: pointer;
  font-size: 30px;
  width: 30px;
  height: 30px;
}
.testimo-button-prev::after,
.testimo-button-next::after {
  content: unset;
  opacity: 0;
}
.developmentProcess .swiper-button-disabled,
.industriesSlider .swiper-button-disabled,
.platformSlider .swiper-button-disabled {
  display: none;
}

