  font-size: 16px;
  line-height: 24px;
  text-align: center;
  color: #000;
}
.ourProcess .cards {
  --cards-closed-size: 10rem;
  --animation-speed-normal: 0.5s;
  display: flex;
  flex-direction: row;
  justify-content: center;
  gap: 1rem;
  width: 100%;
  padding: 3rem 0;
  overflow: hidden;
}
.ourProcess .cards .card {
  position: relative;
  z-index: 1;
  transition: all var(--animation-speed-normal) ease-in-out;
  cursor: pointer;
  width: var(--cards-closed-size);
  height: 25rem;
  flex: 0 0 var(--cards-closed-size);
  border: 0px;
  background: transparent;
}
.ourProcess .cards .card::before {
  content: "";
  background-color: rgba(0, 0, 0, 0.745);
  width: 100%;
  height: 100%;
  position: absolute;
  border-radius: 15px;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 2;
  transition: 0.5s;
  opacity: 0;
}
.ourProcess .cards .card h5 {
  position: absolute;
  left: 0;
  bottom: -55px;
  color: #000;
  font-size: 16px;
  line-height: 1.3;
  transition: all ease-in 0.3s;
  /* white-space: nowrap; */
}
.ourProcess .cards .card img {
  object-fit: cover;
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 100%;
  z-index: 1;
  transition: all var(--animation-speed-normal) ease-in-out;
  border-radius: 15px;
}
.ourProcess .cards .card .card-infos {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 3;
  color: #fff;
