  transition:
    background 300ms,
    transform 200ms;
  font-weight: 600;
  font-size: 14px;
}
.tatt-user-flow .content .user-flow-btn .button__text {
  position: absolute;
  inset: 0;
  animation: text-rotation 8s linear infinite;
  margin-bottom: 0;
}
.tatt-user-flow .content .user-flow-btn .button__text > span {
  position: absolute;
  inset: -1px;
  transform: rotate(calc(19deg * var(--index)));
}
.tatt-user-flow .content .user-flow-btn .button__circle {
  position: relative;
  width: 40px;
  height: 40px;
  overflow: hidden;
  color: #fff;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.tatt-user-flow .content .user-flow-btn .button__icon--copy {
  position: absolute;
  transform: translate(-150%, 150%);
}
.tatt-user-flow .content .user-flow-btn .button__circle .button__icon {
  transition: transform 0.4s ease;
}
.tatt-user-flow
  .content
  .user-flow-btn
  .button:hover
  .button__circle
  .button__icon:not(.button__icon--copy) {
  transform: translate(150%, -150%);
}
.tatt-user-flow
  .content
  .user-flow-btn
  .button:hover
  .button__circle
  .button__icon--copy {
  transform: translate(0, 0);
}
@keyframes text-rotation {
  from {
    rotate: 0deg;
  }
  to {
    rotate: 360deg;
  }
}
