/* =============================================================================
   Soccerfy Case Study
   ============================================================================= */

/* -- Section 1: Banner ------------------------------------------------------- */
.soccerfy-sec1 {
  position: relative;
  margin-top: 80px;
  background-size: cover;
  background-position: center;
  background-image: url("../images/case-studies/soccerfy/banner-wave.webp");
  height: 974px;
  background-repeat: no-repeat;
  padding-top: 60px;
}
.soccerfy-sec1 .prev-btn {
  position: absolute;
  top: 0;
  left: 6%;
  color: #4c525c;
  z-index: 99;
}
.soccerfy-sec1 .prev-btn a {
  color: #0bd86c;
  text-transform: uppercase;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 1px;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: color 0.3s;
}
.soccerfy-sec1 .prev-btn a:hover {
  color: #0056b3;
}
.soccerfy-sec1 .banner-info p {
  font-weight: 600;
  color: #757676;
  padding-right: 52%;
  font-size: 26px;
  margin: 30px 0 25px;
}
.soccerfy-sec1 .banner-info a {
  color: #1eaf62;
  border: 1px solid #1eaf62;
  padding: 10px 17px;
  text-transform: uppercase;
  font-weight: 600;
  font-size: 17px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  transition:
    background-color 0.3s,
    color 0.3s;
}
.soccerfy-sec1 .banner-info a:hover {
  background-color: #1eaf62;
  color: #fff;
}

/* -- Section 2: This is Soccerfy --------------------------------------------- */
.soccerfy-sec2 .soccerfy-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
}
.soccerfy-sec2 .soccerfy-grid .left-info img {
  width: auto;
  height: auto;
}
.soccerfy-sec2 .soccerfy-grid .right-info h2 {
  color: #0bd769;
  font-weight: 700;
  font-size: 60px;
  padding-right: 10%;
  margin-bottom: 20px;
  line-height: 60px;
}
.soccerfy-sec2 .soccerfy-grid .right-info p {
  color: #55e289;
  font-size: 24px;
}
.soccerfy-sec2 .soccerfy-grid .right-info .num-circle {
  color: #159640;
  font-size: 25px;
  position: relative;
  display: inline-block;
  margin: 0 0 30px 0;
  padding: 30px;
  background-image: url("../images/case-studies/soccerfy/num.webp");
  background-repeat: no-repeat;
  background-size: contain;
}

/* -- Section 3: Stay Updated ------------------------------------------------- */
.soccerfy-sec3 {
  background: #0bd769;
  color: #fff;
  padding: 180px 0 0;
  margin-top: -200px;
}
.soccerfy-sec3 .stay-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
}
.soccerfy-sec3 .stay-grid .left-info ul {
  padding: 0;
  margin: 140px 0 0;
  list-style: none;
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
}
.soccerfy-sec3 .stay-grid .left-info ul li {
  background: #fff;
  margin: 0;
  padding: 70px 0 0 0;
  height: 275px;
  width: 275px;
  color: #0bd769;
  text-align: center;
  box-shadow: 0 0 10px 1px #5a5a5a;
}
.soccerfy-sec3 .stay-grid .left-info ul li p {
  font-size: 25px;
  font-weight: 700;
  margin: 13px 0;
}
.soccerfy-sec3 .stay-grid .left-info ul .soc_icon2 {
  transform: translate(-50px, 140px);
}
.soccerfy-sec3 .stay-grid .left-info ul .soc_icon3 {
  transform: translate(0, 90px);
}
.soccerfy-sec3 .stay-grid .left-info ul .soc_icon4 {
  transform: translate(-50px, 270px);
}
.soccerfy-sec3 .stay-grid .left-info ul .soc_icon5 {
  transform: translate(30px, 220px);
}
.soccerfy-sec3 .stay-grid .right-info {
  text-align: right;
}
.soccerfy-sec3 .stay-grid .right-info h2 {
  font-weight: 700;
  font-size: 60px;
  line-height: 65px;
  margin-bottom: 30px;
}
.soccerfy-sec3 .stay-grid .right-info p {
  font-size: 25px;
  margin-bottom: 70px;
}
.soccerfy-sec3 .stay-grid .right-info .num-circle {
  color: #fff;
  filter: brightness(50);
  font-size: 25px;
  position: relative;
  display: inline-block;
  margin: 0 0 30px 0;
  padding: 30px;
  background-image: url("../images/case-studies/soccerfy/num.webp");
  background-repeat: no-repeat;
  background-size: contain;
