/* ============================================================
   THE WEDDING APP — WeddingBanner
   ============================================================ */
.wedding-app {
  background-size: cover;
  background-repeat: no-repeat;
  padding: 80px 0 160px;
  position: relative;
}
.wedding-app .content {
  text-align: center;
}
.wedding-app .content h1, .wedding-app .content h2 {
  color: #000;
  font-weight: bold;
  font-size: 55px;
  margin: 20px 0 30px;
}
.wedding-app .content h1 span {
  color: #a49786;
}
.wedding-app .content p {
  color: #000;
  font-size: 18px;
  font-weight: 500;
  line-height: 2;
}
.wedding-app .content button {
  background-color: #a49786;
  border-radius: 50px;
  padding: 20px;
  text-transform: capitalize;
  font-weight: 400;
  font-size: 18px;
  color: #fff;
  border: none;
  cursor: pointer;
  transition: background-color 0.3s;
}
.wedding-app .content .image {
  padding-top: 80px;
}
.wedding-app::before {
  content: "";
  position: absolute;
  background-image: url("../images/case-studies/wedding-app/gradient.png");
  width: 100%;
  height: 40%;
  background-size: cover;
  bottom: 0;
  background-repeat: no-repeat;
}
.wedding-app.wedding-app-footer {
  padding: 80px 0 0;
}
.wedding-app.wedding-app-footer .content h2 {
  color: #fff;
}
.wedding-app.wedding-app-footer .content button {
  background-color: #fff;
  color: #000;
}
.wedding-app.wedding-app-footer .content button:hover {
  color: #fff;
  background-color: #a49786;
}
.wedding-app.wedding-app-footer::before {
  display: none;
}
@media (max-width: 1024px) {
  .wedding-app .content h1, .wedding-app .content h2 {
    font-size: 45px;
  }
  .wedding-app .content p {
    font-size: 16px;
  }
  .wedding-app .content button {
    padding: 18px;
  }
}
@media (max-width: 768px) {
  .wedding-app .content h1, .wedding-app .content h2 {
    font-size: 35px;
  }
  .wedding-app .content p {
