  background-position: bottom;
  background-repeat: no-repeat;
  background-size: 100% 60%;
}
.tatt-slider .slides-here img {
  width: 100%;
  height: auto;
  object-fit: inherit;
}
.tatt-main-features {
  background: #000;
  padding: 50px 0;
}
.tatt-main-features .content img {
  width: 100%;
  height: auto;
}
.tatt-problems {
  background-color: #000;
  padding: 50px 0 100px;
}
.tatt-problems .main h3 {
  color: #fff;
  text-align: center;
  font-weight: bold;
  font-size: 45px;
}
.tatt-problems .main h3 span {
  color: #c51e06;
}
.tatt-problems .main p {
  color: #fff;
  text-align: center;
}
.tatt-problems .grid-sec {
  display: grid;
  grid-template-columns: 1fr 1fr;
  padding-top: 70px;
}
.tatt-problems .grid-sec .image img {
  border-radius: 30px;
}
.tatt-problems .grid-sec .image-key {
  display: flex;
  justify-content: end;
}
.tatt-problems .grid-sec .image-key img {
  border-radius: 30px;
}
.tatt-problems .grid-sec .text-challenges h3 {
  color: #fff;
  font-weight: bold;
  font-size: 45px;
  margin-bottom: 25px;
}
.tatt-problems .grid-sec .text-challenges ul {
  list-style: none;
  padding-left: 0;
}
.tatt-problems .grid-sec .text-challenges ul li {
  padding: 16px;
  margin-bottom: 20px;
  border-radius: 10px;
  color: #fff;
  font-size: 18px;
  font-weight: bold;
  line-height: 2;
  background: linear-gradient(
    89deg,
    rgb(208 18 26 / 61%) 0%,
    rgba(38, 0, 1, 0.401) 100%
  );
  position: relative;
}
.tatt-problems .grid-sec .text-challenges ul li::before {
  content: "";
  position: absolute;
  inset: 0;
  padding: 2px;
  background: linear-gradient(90deg, #ec1c24, #79554800);
  border-radius: inherit;
  -webkit-mask:
    conic-gradient(#000 0 0) content-box exclude,
    conic-gradient(#000 0 0);
  mask:
    conic-gradient(#000 0 0) content-box exclude,
    conic-gradient(#000 0 0);
}
.tatt-revolution {
  background-color: #000;
  padding: 50px 0 100px;
}
.tatt-revolution .main {
  display: grid;
  grid-template-columns: 60% 35%;
  background-image: url("../images/case-studies/tatt-ai/rev-bg-tiny.webp");
  border-radius: 30px;
  background-repeat: no-repeat;
  background-size: cover;
  position: relative;
}
.tatt-revolution .main .text {
  padding: 80px 50px;
}
.tatt-revolution .main .text h3 {
  color: #fff;
  font-size: 45px;
  font-weight: bold;
  line-height: 1.5;
  margin-bottom: 20px;
}
.tatt-revolution .main .text a {
  color: #000;
  background-color: #fff;
  padding: 15px;
  display: inline-block;
  text-decoration: none;
  transition: color 0.3s;
}
.tatt-revolution .main .text a:hover {
  color: #fff;
}
.tatt-revolution .main::before {
  content: "";
  position: absolute;
  background-image: url("../images/case-studies/tatt-ai/mob-rev.png");
  width: 353px;
  height: 607px;
  background-size: contain;
  right: 0;
  bottom: 0;
  background-repeat: no-repeat;
}
