/* ============================================================
   PORTFOLIO — PortfolioGrid (Portfolio.module.scss flat CSS)
   ============================================================ */
.main-wrapper-container {
  max-width: 2100px;
  margin: auto;
}
.main-wrapper-container .first-grid {
  display: grid;
  grid-gap: 0;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  grid-auto-rows: 321px;
  grid-auto-flow: dense;
}
.main-wrapper-container .first-grid .grid-item {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
}
.main-wrapper-container .first-grid .grid-item a {
  height: 100%;
  overflow: hidden;
  width: 100%;
}
.main-wrapper-container .first-grid .grid-item .overlay {
  position: absolute;
  pointer-events: none;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  opacity: 1;
  transition: 0.4s all ease-in-out;
  margin: auto;
  background: rgba(0, 0, 0, 0.7);
  width: 100%;
  height: 100%;
  flex-direction: column;
}
.main-wrapper-container .first-grid .grid-item .overlay img {
  transition: 0.5s;
  height: auto;
  transform: scale(0.8);
