    radial-gradient(
      900px 560px at 86% 72%,
      rgba(20, 44, 84, 0.5) 0%,
      transparent 64%
    ),
    linear-gradient(180deg, #0a0f18 0%, #05070b 72%);
  padding: 120px 48px 72px;
  position: relative;
  overflow: hidden;
  min-height: 760px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.plt-banner::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(
    rgba(255, 255, 255, 0.05) 1px,
    transparent 1px
  );
  background-size: 28px 28px;
  opacity: 0.4;
  pointer-events: none;
  -webkit-mask-image: radial-gradient(
    ellipse 80% 70% at 50% 50%,
    #000 30%,
    transparent 80%
  );
  mask-image: radial-gradient(
    ellipse 80% 70% at 50% 50%,
    #000 30%,
    transparent 80%
  );
}

/* ── Two-column grid ── */
.plt-banner__grid {
  position: relative;
  z-index: 2;
  max-width: 1360px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 48px;
  align-items: center;
  width: 100%;
}
.plt-banner__content {
  max-width: 620px;
}

/* ── Breadcrumb nav ── */
.plt-breadcrumb {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 12px 18px;
  background: rgba(0, 0, 0, 0.52);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 6px;
  margin-bottom: 20px;
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 400;
  line-height: 1;
  white-space: nowrap;
  flex-wrap: nowrap;
  list-style: none;
}

.plt-breadcrumb__item {
  color: rgba(255, 255, 255, 0.5);
  text-decoration: none;
  transition: color 0.2s ease;
  white-space: nowrap;
}

a.plt-breadcrumb__item:hover,
a.plt-breadcrumb__item:focus {
  color: rgba(255, 255, 255, 0.85);
  text-decoration: none;
  outline: none;
}

.plt-breadcrumb__item--current {
  color: rgba(255, 255, 255, 0.85);
  font-weight: 500;
  cursor: default;
}

.plt-breadcrumb__sep {
  color: rgba(255, 255, 255, 0.3);
  font-size: 12px;
  line-height: 1;
  flex-shrink: 0;
  user-select: none;
}

@media (max-width: 640px) {
  .plt-breadcrumb {
    font-size: 12px;
    padding: 5px 10px;
    gap: 5px;
  }
}

/* ── Eyebrow tag ── */
.plt-banner__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px 8px 12px;
  border-radius: 999px;
  background: rgba(236, 28, 36, 0.1);
  border: 1px solid rgba(236, 28, 36, 0.25);
  color: #ff6e73;
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  margin-bottom: 24px;
}
.plt-banner__eyebrow::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ec1c24;
  box-shadow: 0 0 10px rgba(236, 28, 36, 0.7);
  flex-shrink: 0;
}

/* ── Heading ── */
.plt-banner__h1 {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: clamp(44px, 5.4vw, 68px);
  font-weight: 700;
  color: #ffffff;
  letter-spacing: -0.035em;
  line-height: 1.04;
  margin: 0 0 24px;
  text-wrap: balance;
}
.plt-banner__h1 .plt-banner__accent {
  color: #ec1c24;
}

/* ── Subheading ── */
.plt-banner__sub {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: clamp(17px, 1.4vw, 20px);
  font-weight: 400;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.65);
  margin: 0 0 36px;
  max-width: 560px;
}

/* ── CTA row ── */
.plt-banner__actions {
  display: flex;
  gap: 14px;
  align-items: center;
  flex-wrap: wrap;
}

/* ── Primary CTA — matches PltHero .plt-btn-primary ── */
.plt-banner__btn-primary.tnb-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  height: 54px;
  padding: 0 26px;
  background: #ec1c24;
  color: #ffffff;
  border: none;
  border-radius: 10px;
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: normal;
  text-transform: none;
  text-decoration: none;
  cursor: pointer;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.plt-banner__btn-primary.tnb-btn::before {
  content: none;
}
.plt-banner__btn-primary.tnb-btn:hover:not(:disabled) {
  color: #ffffff;
  transform: translateY(-2px);
  box-shadow: 0 14px 36px -10px rgba(236, 28, 36, 0.6);
}
.plt-banner__btn-primary.tnb-btn:active {
  transform: translateY(0);
  box-shadow: 0 6px 16px -6px rgba(236, 28, 36, 0.5);
}
.plt-banner__btn-primary.tnb-btn:focus-visible {
  outline: 2px solid rgba(236, 28, 36, 0.6);
  outline-offset: 3px;
}

/* ── Ghost CTA — matches PltHero .plt-btn-ghost ── */
.plt-banner__btn-ghost.tnb-btn.btnTransparent {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  height: 54px;
  padding: 0 26px;
  background: transparent;
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: 10px;
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: normal;
  text-transform: none;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.25s ease;
}
.plt-banner__btn-ghost.tnb-btn.btnTransparent::before {
  content: none;
}
.plt-banner__btn-ghost.tnb-btn.btnTransparent:hover:not(:disabled) {
  background: #ffffff;
  color: #000000;
  border-color: #ffffff;
  box-shadow: 0 10px 30px -14px rgba(255, 255, 255, 0.3);
  transform: translateY(-2px);
}
.plt-banner__btn-ghost.tnb-btn.btnTransparent:active {
  transform: translateY(0);
  box-shadow: none;
}
.plt-banner__btn-ghost.tnb-btn.btnTransparent:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.6);
  outline-offset: 3px;
}

/* ── Responsive — tablet & mobile ── */
@media (max-width: 640px) {
  .plt-banner__actions {
    gap: 12px;
  }
  .plt-banner__btn-primary.tnb-btn,
  .plt-banner__btn-ghost.tnb-btn.btnTransparent {
    font-size: 14px;
    height: 48px;
    padding: 0 22px;
    width: 100%;
    justify-content: center;
  }
}

/* ── Platform tile grid (right column) ── */
.plt-banner__grid-wrap {
  width: 100%;
  max-width: 640px;
  margin-left: auto;
  padding: 38px 0;
  -webkit-mask-image: linear-gradient(
    180deg,
    transparent 0%,
    #000 15%,
    #000 85%,
    transparent 100%
  );
  mask-image: linear-gradient(
    180deg,
    transparent 0%,
    #000 15%,
    #000 85%,
    transparent 100%
  );
}
.plt-banner__tilegrid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  grid-auto-rows: 104px;
  gap: 14px;
}
.plt-banner__tile {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 11px;
  background: rgba(20, 24, 32, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 18px;
  box-shadow: 0 20px 44px -26px rgba(0, 0, 0, 0.85);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    border-color 0.3s ease,
    background 0.3s ease;
  position: relative;
  z-index: 1;
  overflow: hidden;
}
.plt-banner__tile:hover {
  transform: translateY(-5px);
  border-color: rgba(236, 28, 36, 0.45);
  background: rgba(28, 32, 42, 0.95);
  box-shadow: 0 28px 56px -26px rgba(236, 28, 36, 0.5);
  z-index: 2;
}
.plt-banner__tile--wide {
  grid-column: span 2;
}
.plt-banner__tile-ic {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.plt-banner__tile-ic img {
  width: 40px;
  height: 40px;
  object-fit: contain;
  display: block;
}
.plt-banner__tile--wide .plt-banner__tile-ic img {
  max-width: 150px;
  height: 100%;
  width: 100%;
}
.plt-banner__tile-name {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.85);
  letter-spacing: -0.01em;
  white-space: nowrap;
}

/* ── Animation: assemble (fly-in, staggered via nth-child) ── */
@keyframes pltBannerAssemble {
  from {
    opacity: 0;
    transform: translateY(26px) scale(0.88);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
.plt-banner__tilegrid--assemble .plt-banner__tile {
  opacity: 0;
  animation: pltBannerAssemble 0.7s cubic-bezier(0.18, 0.9, 0.32, 1.1) forwards;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(1) {
  animation-delay: 0s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(2) {
  animation-delay: 0.08s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(3) {
  animation-delay: 0.16s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(4) {
  animation-delay: 0.24s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(5) {
  animation-delay: 0.32s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(6) {
  animation-delay: 0.4s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(7) {
  animation-delay: 0.48s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(8) {
  animation-delay: 0.56s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(9) {
  animation-delay: 0.64s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(10) {
  animation-delay: 0.72s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(11) {
  animation-delay: 0.8s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(12) {
  animation-delay: 0.88s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(13) {
  animation-delay: 0.96s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(14) {
  animation-delay: 1.04s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(15) {
  animation-delay: 1.12s;
}
.plt-banner__tilegrid--assemble .plt-banner__tile:nth-child(n + 16) {
  animation-delay: 1.2s;
}

/* ── Animation: float (gentle bob) ── */
@keyframes pltBannerFloat {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-7px);
  }
}
.plt-banner__tilegrid--float .plt-banner__tile {
  animation: pltBannerFloat 5s ease-in-out infinite;
}
.plt-banner__tilegrid--float .plt-banner__tile:nth-child(odd) {
  animation-delay: 0s;
}
.plt-banner__tilegrid--float .plt-banner__tile:nth-child(even) {
  animation-delay: 0.6s;
}
.plt-banner__tilegrid--float .plt-banner__tile:nth-child(3n) {
  animation-delay: 1.2s;
}

/* ── Animation: pulse (red glow sweep) ── */
@keyframes pltBannerPulse {
  0%,
  60%,
  100% {
    background: rgba(20, 24, 32, 0.9);
    border-color: rgba(255, 255, 255, 0.1);
  }
  30% {
    background: rgba(40, 22, 26, 0.95);
    border-color: rgba(236, 28, 36, 0.6);
    box-shadow: 0 0 26px -4px rgba(236, 28, 36, 0.55);
  }
}
.plt-banner__tilegrid--pulse .plt-banner__tile {
  animation: pltBannerPulse 3s ease-in-out infinite;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(1) {
  animation-delay: 0s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(2) {
  animation-delay: 0.2s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(3) {
  animation-delay: 0.4s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(4) {
  animation-delay: 0.6s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(5) {
  animation-delay: 0.8s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(6) {
  animation-delay: 1s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(7) {
  animation-delay: 1.2s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(8) {
  animation-delay: 1.4s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(9) {
  animation-delay: 1.6s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(10) {
  animation-delay: 1.8s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(11) {
  animation-delay: 2s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(12) {
  animation-delay: 2.2s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(13) {
  animation-delay: 2.4s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(14) {
  animation-delay: 2.6s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(15) {
  animation-delay: 2.8s;
}
.plt-banner__tilegrid--pulse .plt-banner__tile:nth-child(n + 16) {
  animation-delay: 3s;
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  .plt-banner__tile {
    animation: none !important;
    opacity: 1 !important;
  }
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .plt-banner {
    padding: 100px 32px 64px;
    min-height: 640px;
  }
  .plt-banner__grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .plt-banner__content {
    max-width: 100%;
  }
  .plt-banner__grid-wrap {
    max-width: 520px;
    margin: 0 auto;
  }
}
@media (max-width: 640px) {
  .plt-banner {
    padding: 90px 20px 56px;
  }
  .plt-banner__tilegrid {
    grid-template-columns: repeat(3, 1fr);
    grid-auto-rows: 88px;
    gap: 10px;
  }
/*   .plt-banner__tile-ic img {
    width: 32px;
    height: 32px;
  }
  .plt-banner__tile--wide .plt-banner__tile-ic img {
    width: 30px;
    height: 30px;
  } */
  .plt-banner__tile-name {
    font-size: 11px;
  }
}

/* =============================================================
   TECHNBRAINS — TRUST SLIDER  (.ts-*)
   Layout   : trust_slider
   Component: template-parts/components/Trust-slider.php
   ============================================================= */

/* ── Section shell ── */
.ts-section {
  background: #ffffff;
  padding: 52px 48px;
  /* border-bottom: 1px solid #e5e5e5; */
}
.ts-section--light {
  background: #f6f7f8;
}
.ts-section--dark {
  background: #0a0f18;
  border-bottom-color: rgba(255, 255, 255, 0.08);
}

.ts-inner {
  max-width: 1360px;
  margin: 0 auto;
}

/* ── Eyebrow label ── */
.ts-label {
  text-align: center;
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #555555;
  margin: 0 0 32px;
}
.ts-section--dark .ts-label {
  color: rgba(255, 255, 255, 0.5);
}
.ts-desc {
  text-align: center;
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  color: #555555;
  max-width: 720px;
  margin: -20px auto 32px;
}
.ts-section--dark .ts-desc {
  color: rgba(255, 255, 255, 0.6);
}
/* ── Marquee container — masks edges, clips overflow ── */
.ts-marquee {
  position: relative;
  overflow: hidden;
  width: 100%;
  -webkit-mask-image: linear-gradient(
    90deg,
    transparent 0%,
    #000 9%,
    #000 91%,
    transparent 100%
  );
  mask-image: linear-gradient(
    90deg,
    transparent 0%,
    #000 9%,
    #000 91%,
    transparent 100%
  );
}

/* ── Scrolling track — items duplicated 2× in PHP for seamless -50% loop ── */
.ts-track {
  display: flex;
  width: max-content;
  align-items: center;
  gap: 12px;
  animation: tsMarquee 40s linear infinite;
  will-change: transform;
}

/* Pause on hover / focus */
.ts-marquee:hover .ts-track,
.ts-marquee:focus-within .ts-track {
  animation-play-state: paused;
}

@keyframes tsMarquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .ts-track {
    animation: none;
  }
  .ts-marquee {
    overflow-x: auto;
    -webkit-mask-image: none;
    mask-image: none;
  }
}

/* ── Individual trust pill ── */
.ts-item {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 10px 20px;
  background: #ffffff;
  transition:
    transform 0.3s ease,
    border-color 0.3s ease,
    box-shadow 0.3s ease;
  cursor: default;
  white-space: nowrap;
  flex-shrink: 0;
}
.ts-item:hover {
  transform: translateY(-2px);
  border-color: rgba(236, 28, 36, 0.35);
  box-shadow: 0 8px 24px -12px rgba(12, 35, 64, 0.18);
}
.ts-section--dark .ts-item {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.12);
}
.ts-section--dark .ts-item:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(236, 28, 36, 0.5);
}
.ts-section--light .ts-item {
  background: #ffffff;
}

/* ── Logo image ── */
.ts-item-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  /* height: 28px; */
}
.ts-item-icon img {
  max-height: 70px;
  width: auto;
  height: auto;
  /* max-width: 80px; */
  object-fit: contain;
  display: block;
}
.ts-section--dark .ts-item-icon img {
  filter: brightness(0) invert(1);
}

/* ── Item name label ── */
.ts-item-name {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: #0c2340;
  white-space: nowrap;
}
.ts-section--dark .ts-item-name {
  color: rgba(255, 255, 255, 0.9);
}

/* ── Responsive ── */
@media (max-width: 1024px) {
  .ts-section {
    padding: 44px 32px;
  }
}
@media (max-width: 767px) {
  .ts-section {
    padding: 36px 20px;
  }
  .ts-label {
    font-size: 11px;
    margin-bottom: 24px;
  }
  .ts-track {
    gap: 8px;
    animation-duration: 28s;
  }
  .ts-item {
    padding: 8px 14px;
    gap: 8px;
  }
  .ts-item-icon {
    height: 48px;
  }
  .ts-item-icon img {
    height: auto;
    max-height: 48px;
    max-width: 120px;
  }
  .ts-item-name {
    font-size: 13px;
  }
}

