  max-width: 1360px;
  margin: 0 auto;
}

/* ── Header ── */
.pblg-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 32px;
  margin-bottom: 48px;
}

.pblg-head-text {
  text-align: left;
  max-width: 750px;
}

.pblg-cta-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
  color: #0c2340;
  font-weight: 600;
  font-size: 14px;
  text-decoration: none;
  border-bottom: 1px solid #0c2340;
  padding-bottom: 2px;
  transition:
    gap 0.2s ease,
    color 0.2s ease,
    border-color 0.2s ease;
}

.pblg-cta-btn:hover {
  gap: 12px;
  color: #ec1c24;
  border-color: #ec1c24;
}

.pblg-eyebrow {
  display: inline-block;
  padding: 6px 18px;
  border-radius: 999px;
  background: rgba(236, 28, 36, 0.08);
  color: #ec1c24;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.pblg-h2 {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: clamp(36px, 4.2vw, 60px);
  font-weight: 600;
  color: #0c2340;
  letter-spacing: -0.025em;
  line-height: 1.08;
  /* margin: 0; */
  text-wrap: balance;
  text-transform: capitalize;
}

.pblg-desc {
  font-size: 17px;
  color: #555;
  line-height: 1.7;
  margin: 0;
}

/* ── Grid ── */
.pblg-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}

/* ── Card ── */
.pblg-card {
  display: flex;
  flex-direction: column;
  border-radius: 18px;
  overflow: hidden;
  background: #fff;
  border: 1px solid rgba(0, 0, 0, 0.07);
  text-decoration: none;
  color: inherit;
  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease;
}

.pblg-card:hover {
  transform: translateY(-5px);
  box-shadow:
    0 8px 24px -6px rgba(236, 28, 36, 0.18),
    0 24px 48px -12px rgba(236, 28, 36, 0.1);
  text-decoration: none;
}

/* ── Image ── */
.pblg-img {
  width: 100%;
  height: 210px;
  overflow: hidden;
  background: #f3f3f3;
  flex-shrink: 0;
}

.pblg-img-el {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.45s ease;
}

.pblg-card:hover .pblg-img-el {
  transform: scale(1.04);
}

.pblg-img-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #f0f0f0 0%, #e0e0e0 100%);
}

/* ── Body ── */
.pblg-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 24px 24px 26px;
}

.pblg-tag {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #ec1c24;
  margin-bottom: 10px;
}

.pblg-title {
  font-size: 20px;
  font-weight: 700;
  color: #0a0a0a;
  line-height: 1.3;
  margin: 0 0 10px;
  transition: color 0.2s ease;
}

.pblg-card:hover .pblg-title {
  color: #ec1c24;
}

.pblg-excerpt {
  font-size: 14.5px;
  color: #666;
  line-height: 1.65;
  margin: 0 0 16px;
  flex: 1;
}

.pblg-meta {
  font-size: 13px;
  color: #999;
  margin-top: auto;
}

/* ── Responsive ── */
@media (max-width: 1200px) {
  .pblg-section {
    padding: 80px 32px;
  }
}

@media (max-width: 1024px) {
  .pblg-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 900px) {
  .pblg-section {
    padding: 72px 24px;
  }
}

@media (max-width: 640px) {
  .pblg-section {
    padding: 60px 20px;
  }

  .pblg-grid {
    grid-template-columns: 1fr;
  }

  .pblg-head {
    flex-direction: column;
    align-items: flex-start;
    gap: 20px;
    margin-bottom: 36px;
  }
}

@media (max-width: 480px) {
  .pblg-section {
    padding: 52px 16px;
  }

  .pblg-img {
    height: 180px;
  }
}

/* ==========================================================================
   Platform FAQs  (.platform-faqs / .pfaq-*)
   Matches Claude Design PlatformFAQ — white bg, centred head,
   860px accordion list, + icon rotates 45deg to x on open.
   ========================================================================== */

.platform-faqs {
  padding: 90px 48px;
  background: #ffffff;
  font-family: "Outfit", system-ui, sans-serif;
}

.pfaq-container {
  max-width: 1320px;
  margin: 0 auto;
}

/* ── Head ── */
.pfaq-head {
  text-align: center;
  /* max-width: 720px; */
  margin: 0 auto 48px;
}

.pfaq-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  border-radius: 999px;
  background: rgba(236, 28, 36, 0.08);
  color: #ec1c24;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  margin-bottom: 18px;
}

.pfaq-eyebrow::before {
  content: "";
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  flex-shrink: 0;
}

.pfaq-h2 {
  font-size: clamp(36px, 4.2vw, 60px);
  font-weight: 600;
  color: #0c2340;
  letter-spacing: -0.025em;
  line-height: 1.08;
  margin: 0;
}

.pfaq-desc {
  font-size: clamp(17px, 1.4vw, 20px);
  line-height: 1.6;
  color: #555555;
  margin: 20px auto 0;
  max-width: 720px;
}

/* ── List ── */
.pfaq-list {
  max-width: 860px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── Item ── */
.pfaq-item {
  background: #ffffff;
  border: 1px solid #e5e5e5;
  border-radius: 18px;
  overflow: hidden;
  transition:
    border-color 0.25s ease,
    box-shadow 0.25s ease;
}

.pfaq-item.is-open {
  border-color: rgba(236, 28, 36, 0.25);
  box-shadow: 0 8px 24px -12px rgba(236, 28, 36, 0.15);
}
/* ── Question heading wrapper (h3 for SEO/a11y — visual reset only) ── */
.pfaq-item .pfaq-q-title {
  margin: 0;
  padding: 0;
  font-size: inherit;
  font-weight: inherit;
  line-height: inherit;
}

/* ── Question button ── */
.pfaq-q {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 22px 28px;
  background: transparent;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 17px;
  font-weight: 600;
  color: #0c2340;
  line-height: 1.35;
  transition: color 0.2s ease;
}

.pfaq-q:hover {
  color: #ec1c24;
}

.pfaq-q:focus-visible {
  outline: 2px solid #ec1c24;
  outline-offset: -2px;
  border-radius: 17px;
}

/* ── Icon circle ── */
.pfaq-icon {
  width: 28px;
  height: 28px;
  min-width: 28px;
  border-radius: 50%;
  background: rgba(236, 28, 36, 0.08);
  color: #ec1c24;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition:
    background 0.3s ease,
    color 0.3s ease,
    transform 0.3s ease;
}

.pfaq-item.is-open .pfaq-icon {
  background: #ec1c24;
  color: #ffffff;
  transform: rotate(180deg);
}

/* ── Answer panel ── */
.pfaq-a {
  max-height: 0;
  overflow: hidden;
  transition:
    max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1),
    padding 0.3s ease;
  padding: 0 28px;
}

.pfaq-item.is-open .pfaq-a {
  max-height: 800px;
  padding: 0 28px 24px;
}

.pfaq-a p {
  margin: 0 0 10px;
  font-size: 15.5px;
  line-height: 1.65;
  color: #555555;
}

.pfaq-a p:last-child {
  margin-bottom: 0;
}

.pfaq-a ul,
.pfaq-a ol {
  margin: 0 0 10px;
  padding-left: 20px;
  font-size: 15.5px;
  line-height: 1.65;
  color: #555555;
}

.pfaq-a a {
  color: #ec1c24;
  text-decoration: underline;
}

/* ── Responsive ── */
@media (max-width: 1200px) {
  .platform-faqs {
    padding: 80px 32px;
  }
}

@media (max-width: 900px) {
  .platform-faqs {
    padding: 72px 24px;
  }
}

@media (max-width: 640px) {
  .platform-faqs {
    padding: 60px 20px;
  }

  .pfaq-head {
    margin-bottom: 36px;
  }

  .pfaq-q {
    padding: 18px 20px;
    font-size: 16px;
  }

  .pfaq-a {
    padding: 0 20px;
  }

  .pfaq-item.is-open .pfaq-a {
    padding: 0 20px 20px;
  }
}

@media (max-width: 480px) {
  .platform-faqs {
    padding: 52px 16px;
  }

  .pfaq-q {
    padding: 16px;
    font-size: 15px;
    gap: 12px;
  }

  .pfaq-icon {
    width: 24px;
    height: 24px;
    min-width: 24px;
  }

  .pfaq-a {
    padding: 0 16px;
  }

  .pfaq-item.is-open .pfaq-a {
    padding: 0 16px 18px;
  }
}

/* ==========================================================================
   Industry Hub — IHHero + IHIndustries
   Ported from E:\technbrains-claude-design\industries.css
   ========================================================================== */

/* ── CSS custom properties ─────────────────────────────────────────────────── */
:root {
  --ih-red: #ec1c24;
  --ih-accent-soft: rgba(236, 28, 36, 0.1);
  --ih-accent-line: rgba(236, 28, 36, 0.3);
  --ih-accent-glow: rgba(236, 28, 36, 0.35);
  --ih-navy: #0c2340;
  --ih-text: #1a2233;
  --ih-muted: #5a6478;
  --ih-line: #e8e5e0;
  --ih-soft: #f6f5f3;
  --ih-card: #ffffff;
  --ih-pad-y: 90px;
  --ih-pad-x: 80px;
  --ih-container: 1320px;
}

/* ── Shared layout wrappers ─────────────────────────────────────────────────── */
.ih-section {
  padding: var(--ih-pad-y) var(--ih-pad-x);
  position: relative;
}
.ih-section.alt {
  background: var(--ih-soft);
}

.ih-container {
  max-width: var(--ih-container);
  margin: 0 auto;
}

/* ── Eyebrow label ──────────────────────────────────────────────────────────── */
.ih-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--ih-red);
  margin-bottom: 22px;
}
.ih-eyebrow::before {
  content: "";
  width: 28px;
  height: 1px;
  background: var(--ih-red);
  flex-shrink: 0;
}

/* ── Section H2 ─────────────────────────────────────────────────────────────── */
.ih-h2 {
  font-family: "Outfit", "Montserrat", system-ui, sans-serif;
  font-size: clamp(32px, 3.8vw, 56px);
  font-weight: 600;
  line-height: 1.06;
  letter-spacing: -0.025em;
  color: var(--ih-navy);
  margin: 0 0 22px;
  max-width: 920px;
  text-transform: capitalize;
}
.ih-h2 .accent {
  color: var(--ih-red);
}

/* ── Section subtitle ───────────────────────────────────────────────────────── */
.ih-sub {
  font-size: 19px;
  line-height: 1.6;
  color: var(--ih-muted);
  max-width: 760px;
  margin: 0;
}

/* ── IH Buttons ─────────────────────────────────────────────────────────────── */
.ih-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 16px 26px;
  border-radius: 10px;
  font-family: "Outfit", "Montserrat", system-ui, sans-serif;
  font-weight: 600;
  font-size: 15px;
  letter-spacing: 0.005em;
  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease,
    background 0.25s ease,
    color 0.25s ease,
    border-color 0.25s ease;
  cursor: pointer;
  border: 1.5px solid transparent;
  text-decoration: none;
  line-height: 1;
  white-space: nowrap;
}
.ih-btn-primary {
  background: var(--ih-red);
  color: #fff;
  box-shadow: 0 8px 24px -12px rgba(236, 28, 36, 0.45);
}
.ih-btn-primary:hover {
  color: #fff;
  transform: translateY(-2px);
  box-shadow: 0 14px 30px -10px rgba(236, 28, 36, 0.55);
}
.ih-btn svg {
  transition: transform 0.25s ease;
  flex-shrink: 0;
}
.ih-btn:hover svg {
  transform: translateX(3px);
}

/* Ghost button — white text on dark hero */
.ih-oh-ghost {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 16px 26px;
  border-radius: 10px;
  font-family: "Outfit", "Montserrat", system-ui, sans-serif;
  font-weight: 600;
  font-size: 15px;
  cursor: pointer;
  text-decoration: none;
  line-height: 1;
  white-space: nowrap;
  background: transparent;
  color: #ffffff;
  border: 1.5px solid rgba(255, 255, 255, 0.3);
  transition:
    background 0.25s ease,
    color 0.25s ease,
    border-color 0.25s ease,
    transform 0.25s ease;
}
.ih-oh-ghost:hover {
  background: #ffffff;
  color: #0a0a0b;
  border-color: #ffffff;
  transform: translateY(-2px);
}
.ih-oh-ghost svg {
  transition: transform 0.25s ease;
  flex-shrink: 0;
}
.ih-oh-ghost:hover svg {
  transform: translateX(3px);
}

/* ==========================================================================
   IHHero — dark orbit hero section
   ========================================================================== */
.ih-hero.ih-orbithero {
  position: relative;
  min-height: 760px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: #0a0a0b;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

/* background gradient + optional custom bg image */
.ih-oh-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      ellipse 60% 70% at 78% 42%,
      rgba(236, 28, 36, 0.16) 0%,
      transparent 60%
    ),
    radial-gradient(
      ellipse 50% 60% at 12% 88%,
      rgba(40, 80, 180, 0.1) 0%,
      transparent 60%
    ),
    linear-gradient(180deg, #0a0a0b 0%, #0a0a0b 100%);
  background-size: cover;
  background-position: center;
  pointer-events: none;
  z-index: 0;
}

/* two-column content grid */
.ih-oh-grid {
  position: relative;
  z-index: 2;
  max-width: var(--ih-container);
  margin: 0 auto;
  width: 100%;
  padding: 110px var(--ih-pad-x) 96px;
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 48px;
  align-items: center;
}

/* left content column */
.ih-oh-content {
  max-width: 600px;
}

/* optional eyebrow on dark bg */
.ih-oh-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--ih-red);
  margin-bottom: 20px;
}
.ih-oh-eyebrow::before {
  content: "";
  width: 28px;
  height: 1px;
  background: var(--ih-red);
  flex-shrink: 0;
}

/* pulsing-dot badge pill */
.ih-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 7px 16px 7px 12px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.12);
  margin-bottom: 24px;
  font-size: 13px;
  font-weight: 600;
  color: #fff;
  letter-spacing: 0.04em;
  font-family: "Outfit", "Montserrat", system-ui, sans-serif;
}
.ih-hero-badge-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ih-red);
  box-shadow: 0 0 0 4px rgba(236, 28, 36, 0.22);
  animation: ihBadgePulse 2s ease-in-out infinite;
  flex-shrink: 0;
}
@keyframes ihBadgePulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

/* H1 */
.ih-h1 {
  font-family: "Outfit", "Montserrat", system-ui, sans-serif;
  font-size: clamp(38px, 4.8vw, 66px);
  line-height: 1.04;
  letter-spacing: -0.02em;
  font-weight: 600;
  color: #fff;
  margin: 0 0 22px;
}
.ih-h1 .accent,
.ih-h1 span {
  color: var(--ih-red);
}

/* description paragraph */
.ih-oh-sub {
  font-size: 17px;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.62);
  margin: 0 0 32px;
  max-width: 540px;
}

/* CTA row */
.ih-oh-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  align-items: center;
}

/* ==========================================================================
   Right-column orbit visual (pure CSS, replaces React orbit animation)
   ========================================================================== */
.ih-oh-visual {
  position: relative;
  display: grid;
  place-items: center;
  height: 600px;
}

.ih-hero-vis-wrap {
  position: relative;
  width: 460px;
  height: 460px;
  display: grid;
  place-items: center;
}

/* decorative orbit container */
.ih-hero-vis-orbit {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

/* three concentric rings */
.ih-hero-vis-ring {
  position: absolute;
  border-radius: 50%;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.ih-hero-vis-ring.r1 {
  width: 460px;
  height: 460px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  animation: ihRingSpin 60s linear infinite;
}
.ih-hero-vis-ring.r2 {
  width: 320px;
  height: 320px;
  border: 1px solid rgba(236, 28, 36, 0.16);
}
.ih-hero-vis-ring.r3 {
  width: 180px;
  height: 180px;
  border: 1px solid rgba(255, 255, 255, 0.05);
}
@keyframes ihRingSpin {
  from {
    transform: translate(-50%, -50%) rotate(0deg);
  }
  to {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ih-hero-vis-ring.r1 {
    animation: none;
  }
}

/* red radial glow */
.ih-hero-vis-glow {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 340px;
  height: 340px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgba(236, 28, 36, 0.2) 0%,
    transparent 68%
  );
  pointer-events: none;
  animation: ihGlowPulse 4s ease-in-out infinite;
}
@keyframes ihGlowPulse {
  0%,
  100% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
  50% {
    opacity: 0.65;
    transform: translate(-50%, -50%) scale(1.08);
  }
}

/* hero image frame — rounded rect in front of rings */
.ih-hero-vis-card {
  position: relative;
  z-index: 2;
  width: 340px;
  height: 340px;
  border-radius: 28px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow:
    0 0 0 1px rgba(236, 28, 36, 0.08),
    0 30px 80px -20px rgba(0, 0, 0, 0.75),
    0 0 60px rgba(236, 28, 36, 0.14);
}
.ih-hero-vis-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ── IHHero responsive ──────────────────────────────────────────────────────── */
@media (min-width: 1101px) and (max-width: 1536px) {
  .ih-hero.ih-orbithero {
    min-height: fit-content;
  }
  .ih-oh-grid {
    padding: 0 7%;
  }
}

@media (max-width: 1100px) {
  .ih-hero.ih-orbithero {
    min-height: auto;
  }
  .ih-oh-grid {
    grid-template-columns: 1fr;
    gap: 36px;
    padding: 96px 32px 72px;
  }
  .ih-oh-visual {
    height: 480px;
    order: -1;
  }
  .ih-hero-vis-wrap {
    transform: scale(0.88);
  }
}
@media (max-width: 768px) {
  .ih-oh-grid {
    padding: 80px 24px 64px;
  }
  .ih-oh-visual {
    height: 380px;
  }
  .ih-hero-vis-wrap {
    transform: scale(0.72);
  }
}
@media (max-width: 600px) {
  .ih-oh-visual {
    height: 320px;
  }
  .ih-hero-vis-wrap {
    transform: scale(0.62);
  }
  .ih-oh-actions {
    flex-direction: column;
    align-items: stretch;
  }
  .ih-oh-actions .ih-btn,
  .ih-oh-actions .ih-oh-ghost {
    justify-content: center;
    text-align: center;
  }
}
