/* ==========================================================================
   IHStreamViz — 3-column vertical marquee image grid (right-column hero)
   ========================================================================== */
.ih-stream {
  position: relative;
  width: 100%;
  max-width: 460px;
  height: 480px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  overflow: hidden;
  -webkit-mask-image: linear-gradient(
    180deg,
    transparent 0%,
    #000 16%,
    #000 84%,
    transparent 100%
  );
  mask-image: linear-gradient(
    180deg,
    transparent 0%,
    #000 16%,
    #000 84%,
    transparent 100%
  );
}
.ih-stream-lane {
  position: relative;
  overflow: visible;
}
.ih-stream-track {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.ih-stream-track.up {
  animation: ihStreamUp linear infinite;
}
.ih-stream-track.down {
  animation: ihStreamDown linear infinite;
}
@keyframes ihStreamUp {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(-50%);
  }
}
@keyframes ihStreamDown {
  from {
    transform: translateY(-50%);
  }
  to {
    transform: translateY(0);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ih-stream-track {
    animation: none !important;
  }
}
.ih-stream:hover .ih-stream-track {
  animation-play-state: paused;
}
.ih-stream-chip {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: stretch;
  height: 118px;
  border-radius: 16px;
  background: rgba(20, 24, 32, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.1);
  overflow: hidden;
  transition:
    border-color 0.3s ease,
    transform 0.3s ease;
}
.ih-stream-chip:hover {
  border-color: rgba(236, 28, 36, 0.45);
  transform: translateY(-2px);
}
.ih-stream-chip-img {
  width: 100%;
  height: 100%;
  border-radius: 16px;
  overflow: hidden;
  flex: 1;
}
.ih-stream-chip-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  filter: saturate(0.85) brightness(0.82);
  transition:
    filter 0.3s ease,
    transform 0.4s ease;
}
.ih-stream-chip:hover .ih-stream-chip-img img {
  filter: saturate(1) brightness(1);
  transform: scale(1.06);
}
@media (max-width: 1100px) {
  .ih-stream {
    height: 420px;
  }
}
@media (max-width: 600px) {
  .ih-stream {
    height: 340px;
    gap: 10px;
  }
}

