/* ==========================================================================
   IH Case Studies Slider — 3D card deck
   Matches the IHCases component from the Claude Design exactly.
   Base: styles.css .case-deck / .case-card rules.
   ========================================================================== */

/* ── Local CSS tokens (matches Claude Design styles.css :root) ──────────── */
.section.cases {
  --cs-red: #ec1c24;
  --cs-navy: #0c2340;
  --cs-white: #ffffff;
  --cs-line: #e8e5e0;
  --cs-warmgray: #4a4845;
  background: var(--cs-white);
  color: var(--cs-navy);
  overflow-x: clip;
  padding: 90px 0;
}

/* ── Section header — centered (IHCases variant) ────────────────────────── */
.ihcs-head {
  text-align: center;
  justify-content: space-between;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 20px;
}
/* .ihcs-intro {
  margin: 0 auto;
  max-width: 760px;
} */
.ihcs-eyebrow {
  justify-content: center;
}
.ihcs-h2 {
  text-align: left;
  /* max-width: 720px;
  margin-left: auto;
  margin-right: auto; */
  color: var(--cs-navy);
  font-family: "Outfit", system-ui, sans-serif;
  font-size: clamp(36px, 4.2vw, 60px);
  font-weight: 600;
  color: #0c2340;
  letter-spacing: -0.025em;
  line-height: 1.08;
  margin: 0;
  text-wrap: balance;
  text-transform: capitalize;
}
.ihcs-desc {
  margin-top: 16px;
  font-weight: 500;
  max-width: 720px;
  /* margin-left: auto; */
  margin-right: auto;
  text-align: left;
  color: var(--cs-warmgray);
  font-size: 25px;
  line-height: 1.4;
}

/* ── 3D Deck container ──────────────────────────────────────────────────── */
.case-deck {
  position: relative;
  margin: 56px auto 0;
  max-width: 1160px;
  height: 580px;
  perspective: 1600px;
  transform-style: preserve-3d;
}

/* ── Card base ──────────────────────────────────────────────────────────── */
.case-card {
  position: absolute;
  top: 0;
  left: 50%;
  width: 1060px;
  height: auto;
  margin-left: -530px;
  display: grid;
  grid-template-columns: 420px 1fr;
  gap: 0;
  padding: 20px;
  background: var(--cs-white);
  border: 1px solid var(--cs-line);
  border-radius: 28px;
  box-shadow: 0 24px 48px -28px rgba(12, 35, 64, 0.2);
  text-decoration: none;
  color: inherit;
  cursor: pointer;
  transform-style: preserve-3d;
  backface-visibility: hidden;
  will-change: transform, opacity;
  transition:
    transform 0.5s cubic-bezier(0.18, 0.9, 0.3, 1.05),
    opacity 0.4s ease,
    box-shadow 0.4s ease;
}
section.lp-cs .case-card {
	cursor : normal
}
/* ── 3D States ──────────────────────────────────────────────────────────── */
.case-card.is-front {
  transform: translate3d(0, 0, 0) scale(1);
  opacity: 1;
  z-index: 100;
  box-shadow: 0 40px 80px -28px rgba(12, 35, 64, 0.32);
}
.case-card.is-side-l {
  transform: translate3d(-720px, 60px, -320px) scale(0.5) rotateY(22deg);
  transform-origin: center center;
  opacity: 1;
  z-index: 10;
  filter: none;
}
.case-card.is-side-r {
  transform: translate3d(720px, 60px, -320px) scale(0.5) rotateY(-22deg);
  transform-origin: center center;
  opacity: 1;
  z-index: 10;
  filter: none;
}
.case-card.is-far {
  transform: translate3d(0, 0, -500px) scale(0.42);
  opacity: 0;
  z-index: 30;
  pointer-events: none;
}
.case-card.is-side-l:hover {
  transform: translate3d(-720px, 50px, -300px) scale(0.52) rotateY(20deg);
}
.case-card.is-side-r:hover {
  transform: translate3d(720px, 50px, -300px) scale(0.52) rotateY(-20deg);
}

/* ── Image frame ────────────────────────────────────────────────────────── */
.case-art-frame {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 22px;
  overflow: hidden;
  background: #f4f2ee;
}
.case-art-photo {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  z-index: 2;
  /* Retained from live: art is top-anchored, not centre-cropped. */
  object-position: top;
}

/* ── Content body ───────────────────────────────────────────────────────── */
.case-body {
  padding: 28px 36px 28px 44px;
  display: flex;
  flex-direction: column;
  min-width: 0;
  gap: 18px;
}
.case-eyebrow {
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--cs-warmgray);
}
.case-body h3 {
  color: var(--cs-navy);
  font-size: 38px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin: 0;
}
.case-metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px 32px;
}
.case-metric-v {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 42px;
  font-weight: 700;
  color: var(--cs-red);
  letter-spacing: -0.025em;
  line-height: 1;
}
.case-metric-l {
  font-size: 13.5px;
  color: var(--cs-warmgray);
  margin-top: 6px;
  line-height: 1.3;
}
.case-meta {
  display: flex;
  gap: 28px;
  flex-wrap: wrap;
  padding-top: 16px;
  border-top: 1px solid var(--cs-line);
}
.case-meta-row .k {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--cs-warmgray);
  display: block;
  margin-bottom: 4px;
}
.case-meta-row .v {
  font-size: 14.5px;
  color: var(--cs-navy);
  font-weight: 600;
}
.case-desc {
  font-size: 15px;
  color: var(--cs-warmgray);
  line-height: 1.6;
  margin: 0;
}
.case-foot {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  margin-top: auto;
}
.case-link {
  color: var(--cs-navy);
  font-weight: 600;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  border-bottom: 1px solid var(--cs-navy);
  padding-bottom: 2px;
  cursor: pointer;
  transition:
    color 0.2s,
    border-color 0.2s,
    gap 0.2s;
}
.case-link:hover,
.case-card.is-front .case-link:hover {
  color: var(--cs-red);
  border-bottom-color: var(--cs-red);
  gap: 12px;
}

/* ── Navigation ─────────────────────────────────────────────────────────── */
.case-deck-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 36px;
}
.case-deck-nav .case-btn {
  width: 48px;
  height: 48px;
  border-radius: 999px;
  border: 1px solid var(--cs-line);
  background: #fff;
  color: var(--cs-navy);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition:
    background 0.2s,
    color 0.2s,
    border-color 0.2s;
}
.case-deck-nav .case-btn:hover {
  background: var(--cs-red);
  color: #fff;
  border-color: var(--cs-red);
}
/* Dots: 24x24 tap target, 8px visual. See the matching block in homepage.css — the
   button is the target and ::before is the visible dot, because WCAG 2.2 SC 2.5.8 needs
   24x24 (or non-overlapping 24px spacing) and the old 8px button on a 16px pitch failed
   both. Kept in sync with homepage.css apart from the palette token: this file reads
   --cs-red, which about-v2.css re-points for that page. */
.case-deck-dots {
  display: flex;
  gap: 0;
  align-items: center;
}
.case-deck-dot {
  width: 24px;
  height: 24px;
  background: transparent;
  border: 0;
  padding: 0;
  border-radius: 0;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.case-deck-dot::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(10, 10, 11, 0.18);
  transition:
    background 0.2s,
    width 0.2s;
}
.case-deck-dot.is-active::before {
  background: var(--cs-red);
  width: 24px;
  border-radius: 4px;
}



/* ── Archive pagination ─────────────────────────────────────────────────────
   Styles the_posts_pagination() / paginate_links() output on the blog index and
   category archives, centred and matching the .case-deck-nav controls above.

   Selectors are .navigation.pagination, not .pagination on its own: Bootstrap 5
   is loaded from CDN on every page and defines .pagination { display: flex }
   for its own <ul> component. Matching both classes gives (0,2,0), so these win
   regardless of stylesheet order, and the nav is explicitly reset to block so
   Bootstrap cannot turn the wrapper into a flex row.

   Palette comes from the global :root --ih-* tokens rather than the case deck's
   --cs-* ones, which are scoped to .section.cases and do not exist here. */
.navigation.pagination {
  display: block;
  margin-top: 48px;
  padding-left: 0;
  list-style: none;
}
.navigation.pagination .nav-links {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
/* One shared box for numbers, prev/next and the ellipsis. min-width with
   horizontal padding keeps single digits circular while letting "Previous" and
   "Next" grow into pills. */
.navigation.pagination .page-numbers {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  height: 44px;
  padding: 0 14px;
  border: 1px solid var(--ih-line);
  border-radius: 999px;
  background: var(--ih-card);
  color: var(--ih-navy);
  font-size: 15px;
  font-weight: 600;
  line-height: 1;
  text-decoration: none;
  transition:
    background 0.2s,
    color 0.2s,
    border-color 0.2s;
}
.navigation.pagination a.page-numbers:hover,
.navigation.pagination a.page-numbers:focus-visible {
  background: var(--ih-red);
  border-color: var(--ih-red);
  color: #fff;
}
.navigation.pagination .page-numbers.current {
  background: var(--ih-red);
  border-color: var(--ih-red);
  color: #fff;
}
/* The ellipsis is not interactive, so it drops the button treatment. */
.navigation.pagination .page-numbers.dots {
  border-color: transparent;
  background: none;
  color: var(--ih-muted);
  min-width: 24px;
  padding: 0 4px;
}
@media (max-width: 576px) {
  .navigation.pagination { margin-top: 32px; }
  .navigation.pagination .nav-links { gap: 8px; }
  .navigation.pagination .page-numbers {
    min-width: 38px;
    height: 38px;
    padding: 0 11px;
    font-size: 14px;
  }
}

/* ── View-all CTA ───────────────────────────────────────────────────────── */
.ih-cases-view-all {
  display: flex;
  justify-content: center;
  margin-top: 0px;
}

/* ── Responsive — ≤1280px: flat stacked list ────────────────────────────── */
