/* ═══════════════════════════════════════════════════════════════════════════
   IH Flexible Engagement Models  (.ih-engage-*)
   Matches IHEngage from Claude Design — 3-column card grid
   ═══════════════════════════════════════════════════════════════════════════ */

.ih-engage-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.ih-engage-card {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 36px 32px 32px;
  background: #fff;
  border: 1px solid var(--ih-line, #e4e8f0);
  border-radius: 16px;
  position: relative;
  transition:
    box-shadow 0.22s ease,
    transform 0.22s ease;
  text-decoration: none;
  color: inherit;
}

a.ih-engage-card:hover {
  border-color: rgba(236, 28, 36, 0.32);
