/* Experts + Testimonials */

.ih-experts-section {
  position: relative;
	  /* Contain the decorative shell ::before glow (extends 40px past the
     shell's right edge) so it can't create horizontal page overflow. */
  overflow-x: clip;
}
.ih-experts-head-row {
  display: block;
  margin-bottom: 40px;
}
.ih-experts-head-left {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  text-align: left;
  max-width: 100%;
}
.ih-experts-head-title-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 32px;
  align-items: center;
  margin-bottom: 16px;
}
.ih-experts-head-title-row .ih-h2 {
  margin: 0;
  max-width: 760px;
}
.ih-experts-head-left .ih-eyebrow {
  justify-content: flex-start;
}
.ih-experts-head-left .ih-sub {
  margin-left: 0;
  max-width: 720px;
}
.ih-experts-head-cta {
  flex-shrink: 0;
  white-space: nowrap;
  justify-self: end;
}
@media (max-width: 900px) {
  .ih-experts-head-title-row {
    grid-template-columns: 1fr;
    gap: 16px;
  }
	  .ih-experts-head-title-row .ih-h2 {
    text-align: center;
  }
  .ih-experts-head-cta {
    margin: auto;
  }
  .ih-experts-head-left .ih-sub {
    text-align: center;
  }
}
.ih-experts-shell {
  position: relative;
  margin-top: 56px;
  display: grid;
  grid-template-columns: 168px 1fr;
  gap: 36px;
  align-items: center;
  max-width: 1080px;
  margin-left: auto;
  margin-right: auto;
}
.ih-experts-shell::before {
  content: "";
  position: absolute;
  top: 40px;
  right: -40px;
  width: 220px;
  height: 220px;
  background:
    radial-gradient(
      circle,
      transparent 60%,
      rgba(12, 35, 64, 0.04) 60.5%,
      transparent 62%
    ),
    radial-gradient(
      circle,
      transparent 70%,
      rgba(12, 35, 64, 0.06) 70.5%,
      transparent 72%
    );
  pointer-events: none;
  opacity: 0.6;
  z-index: 0;
}
.ih-experts-rail {
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: relative;
  z-index: 2;
  align-items: flex-start;
}
.ih-experts-thumb {
  position: relative;
  width: 168px;
  height: 100px;
  border-radius: 20px;
  overflow: hidden;
  background: #efede9;
  cursor: pointer;
  border: 0;
  padding: 0;
  outline: none;
  transition:
    width 0.7s cubic-bezier(0.25, 0.9, 0.3, 1.05),
    height 0.7s cubic-bezier(0.25, 0.9, 0.3, 1.05),
    border-radius 0.7s cubic-bezier(0.25, 0.9, 0.3, 1.05),
    transform 0.7s cubic-bezier(0.25, 0.9, 0.3, 1.05),
    filter 0.6s ease,
    opacity 0.6s ease,
    box-shadow 0.6s ease;
  isolation: isolate;
  flex-shrink: 0;
  filter: blur(2px);
  opacity: 0.6;
  will-change: width, height, transform, filter, opacity;
}
.ih-experts-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 25%;
  filter: saturate(0.5) contrast(1.02) brightness(0.95);
  transition:
    filter 0.4s ease,
    transform 0.5s ease;
}
.ih-experts-thumb:hover {
  transform: translateY(-2px);
}
.ih-experts-thumb:hover img {
  filter: saturate(0.85) contrast(1.05);
}
.ih-experts-thumb::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  border: 2px solid transparent;
  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease;
  pointer-events: none;
  z-index: 3;
}
.ih-experts-thumb.is-active {
  width: 168px;
  height: 184px;
  border-radius: 26px;
  transform: translateX(-12px);
  filter: none;
  opacity: 1;
  box-shadow: 0 24px 40px -20px rgba(236, 28, 36, 0.35);
}
.ih-experts-thumb.is-active::after {
  border-color: var(--ih-red, #ec1c24);
  box-shadow: 0 0 0 4px rgba(236, 28, 36, 0.1);
}
.ih-experts-thumb.is-active img {
  filter: saturate(1) contrast(1.05) brightness(1);
}
.ih-experts-stage {
  display: grid;
  position: relative;
  z-index: 2;
}
.ih-experts-card {
  grid-area: 1 / 1;
  position: relative;
  background: #ffffff;
  border-radius: 28px;
  padding: 44px 56px;
  box-shadow: 0 30px 60px -36px rgba(12, 35, 64, 0.22);
  border: 1px solid var(--ih-line, #e4e8f0);
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 18px;
  min-height: 640px;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
}
.ih-experts-card.is-active {
  opacity: 1;
  pointer-events: auto;
  visibility: visible;
  animation: ihExpertSwap 0.55s cubic-bezier(0.25, 0.9, 0.3, 1.05);
}
@keyframes ihExpertSwap {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.ih-experts-role {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ih-red, #ec1c24);
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.ih-experts-role::before {
  content: "";
  width: 24px;
  height: 1px;
  background: var(--ih-red, #ec1c24);
}
.ih-experts-card h3 {
  font-size: clamp(26px, 2.6vw, 34px);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--ih-navy, #0c2340);
  margin: 0;
  max-width: 92%;
}
.ih-experts-desc {
  font-size: 15.5px;
  line-height: 1.65;
  color: var(--ih-muted, #5a6478);
  margin: 0;
  max-width: 92%;
}
.ih-experts-bullets {
  list-style: none;
  padding: 0;
  margin: 4px 0 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.ih-experts-bullets li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 14px;
  background: var(--ih-soft, #f4f6fa);
  border-radius: 12px;
  font-size: 13px;
  line-height: 1.4;
  color: #2a3550;
  font-weight: 500;
}
.ih-experts-bullets li::before {
  content: "";
  flex-shrink: 0;
  width: 6px;
  height: 6px;
  margin-top: 6px;
  background: var(--ih-red, #ec1c24);
  border-radius: 50%;
}
@media (min-width: 901px) and (max-width: 1280px) {
  .ih-experts-card {
    min-height: 560px;
    padding: 40px 44px;
  }
}

@media (max-width: 900px) {
  .ih-experts-shell {
    grid-template-columns: 1fr;
    gap: 24px;
  }
	
	 .ih-experts-shell::before {
    display: none;
  }
	
  .ih-experts-rail {
    flex-direction: row;
    justify-content: center;
    flex-wrap: wrap;
    align-items: center;
  }
  .ih-experts-thumb {
       width: 120px;
    height: 130px;
    transform: translateY(-0px);
  }
  .ih-experts-thumb.is-active {
    width: 120px;
    height: 130px;
     transform: translateY(-0px);
  }
  .ih-experts-card {
    padding: clamp(22px, 5.5vw, 36px) clamp(18px, 4.5vw, 28px) clamp(20px, 5vw, 28px);
    min-height: auto;
  }
	  .ih-experts-card h3,
  .ih-experts-desc {
    max-width: 100%;
  }
	
  .ih-experts-bullets {
    grid-template-columns: 1fr;
  }
}

/* Testimonials */
.ih-ts-section {
