  border-color: #fff;
}
.hd-btn-secondary:hover {
  background: #fff;
  color: #000;
  border-color: #fff;
  box-shadow: 0 10px 30px -14px rgba(255, 255, 255, 0.3);
  transform: translateY(-2px);
  text-decoration: none;
}

/* ── Hero ── */
.hd-hero {
  position: relative;
  background: #000000;
  min-height: 760px;
  padding: 0 48px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  overflow: hidden;
}
.hd-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      900px 600px at 78% 50%,
      rgba(236, 28, 36, 0.16),
      transparent 60%
    ),
    radial-gradient(
      700px 500px at 10% 0%,
      rgba(12, 35, 64, 0.45),
      transparent 70%
    );
  pointer-events: none;
  z-index: 0;
}

.hd-hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  gap: 60px;
  align-items: center;
  min-height: 760px;
  padding: 140px 0 80px;
  position: relative;
  z-index: 2;
}

.hd-hero-content {
  position: relative;
  z-index: 2;
}

.hd-hero-content h1 {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: clamp(48px, 5.6vw, 75px);
  font-weight: 700;
  line-height: 1.02;
  letter-spacing: -0.035em;
  color: #fff;
  margin-bottom: 28px;
  max-width: 700px;
}
.hd-hero-content h1 .hd-hero-accent {
  color: #ec1c24;
}

.hd-hero-sub {
  font-size: 19px;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.72);
  max-width: 560px;
  margin-bottom: 40px;
  font-weight: 400;
}

.hd-hero-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

/* Orbit canvas wrap */
.hd-orbit-wrap {
  position: relative;
  height: 640px;
  pointer-events: none;
  overflow: visible;
}
.hd-orbit-canvas {
  display: block;
  position: absolute;
  top: -120px;
  left: 0;
}

/* ── Available Devs ── */
.hd-devs {
  background: #0a0a0a;
  padding: 100px 48px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.hd-devs .hd-section-head {
  margin-bottom: 0;
}

.hd-devs-rail {
  margin-top: 56px;
  position: relative;
  overflow: hidden;
  mask-image: linear-gradient(
    90deg,
    transparent 0,
    #000 5%,
    #000 95%,
    transparent 100%
  );
  -webkit-mask-image: linear-gradient(
    90deg,
    transparent 0,
    #000 5%,
    #000 95%,
    transparent 100%
  );
}
.hd-devs-track {
  display: flex;
  gap: 20px;
  width: max-content;
  animation: hdDevScroll 60s linear infinite;
}
.hd-devs-rail:hover .hd-devs-track {
  animation-play-state: paused;
}

.hd-dev-card {
  flex: 0 0 280px;
  background: #231f20;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 20px;
  padding: 20px;
  position: relative;
  transition: all 0.3s ease;
}
.hd-dev-card:hover {
  border-color: rgba(236, 28, 36, 0.4);
  transform: translateY(-4px);
  box-shadow: 0 20px 50px -20px rgba(236, 28, 36, 0.35);
}

.hd-dev-avail {
  position: absolute;
  top: 14px;
  right: 14px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  letter-spacing: 0.06em;
  font-weight: 600;
  color: #29d27d;
  background: rgba(41, 210, 125, 0.1);
  border: 1px solid rgba(41, 210, 125, 0.3);
  padding: 5px 9px;
  border-radius: 100px;
}
.hd-dev-avail::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #29d27d;
  box-shadow: 0 0 8px rgba(41, 210, 125, 0.8);
  animation: hdPulse 1.6s ease-in-out infinite;
}

.hd-dev-photo {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  overflow: hidden;
  margin-bottom: 16px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: #1a1718;
}
.hd-dev-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  filter: grayscale(0.2);
}
.hd-dev-photo-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #2a2a2a, #1a1a1a);
}

.hd-dev-name {
  font-size: 17px;
  font-weight: 600;
  color: #fff;
  margin-bottom: 14px;
}

.hd-dev-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.hd-dev-tag {
  font-size: 11px;
  padding: 4px 9px;
  border-radius: 100px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.7);
}

.hd-dev-meta {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  justify-content: space-between;
  font-size: 11.5px;
  color: rgba(255, 255, 255, 0.5);
  letter-spacing: 0.02em;
}
.hd-dev-meta strong {
  color: #fff;
  font-weight: 600;
}

/* ── Metrics ── */
.hd-metrics {
  background: #111111;
  padding: 90px 48px;
  position: relative;
  overflow: hidden;
}

.hd-metrics-row {
  margin-top: 80px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  flex-wrap: wrap;
}

.hd-metrics-divider {
  width: 1px;
  height: 72px;
  background: linear-gradient(
    180deg,
    transparent,
    rgba(255, 255, 255, 0.14) 25%,
    rgba(255, 255, 255, 0.14) 75%,
    transparent
  );
  flex-shrink: 0;
}

.hd-metric-item {
  flex: 1;
  text-align: center;
  padding: 28px 24px;
  transition: transform 0.3s ease;
  min-width: 160px;
}
.hd-metric-item:hover {
  transform: translateY(-2px);
}

.hd-metric-num {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: clamp(40px, 4vw, 60px);
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.04em;
  line-height: 1;
  margin-bottom: 12px;
}
.hd-metric-num .suffix {
  color: #ec1c24;
  font-size: 0.42em;
  margin-left: 3px;
  font-weight: 700;
}

.hd-metric-item.is-featured .hd-metric-num {
  color: #fff;
  font-size: clamp(46px, 4.5vw, 68px);
}
.hd-metric-item.is-featured .hd-metric-num .suffix {
  color: #ec1c24;
}

.hd-metric-label {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.65);
  line-height: 1.45;
}

/* Recognised By */
.hd-recog-strip {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 32px;
  align-items: center;
  margin-top: 72px;
  padding: 28px 0 0;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}
.hd-recog-label {
  font-size: 13px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.45);
  letter-spacing: 0.01em;
  flex-shrink: 0;
  white-space: nowrap;
}
.hd-recog-marquee {
  position: relative;
  overflow: hidden;
  mask-image: linear-gradient(
    90deg,
    transparent 0,
    #000 60px,
    #000 calc(100% - 60px),
    transparent 100%
  );
  -webkit-mask-image: linear-gradient(
    90deg,
    transparent 0,
    #000 60px,
    #000 calc(100% - 60px),
    transparent 100%
  );
}
.hd-recog-track {
  display: flex;
  gap: 56px;
  width: max-content;
  animation: hdRecogScroll 30s linear infinite;
}
.hd-recog-marquee:hover .hd-recog-track {
  animation-play-state: paused;
}

.hd-recog-item {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 36px;
  opacity: 0.7;
  transition: opacity 0.2s ease;
}
.hd-recog-item:hover {
  opacity: 1;
}

.hd-recog-logo-img {
  max-height: 30px;
  width: auto;
  display: block;
  /* filter: invert(1) brightness(0.9); */
}

/* ── Responsive ── */
@media (max-width: 1200px) {
  .hd-hero {
    padding: 0 32px;
  }
  .hd-devs {
    padding: 80px 32px;
