/* ============================================================
   HD. Services (hd_services)
   ============================================================ */
.hd-services {
  background: #111111;
 padding: 90px 48px;
}
.hd-services .hd-sub {
  color: rgba(255, 255, 255, 0.6);
}
.hd-services-shell {
  background: transparent;
  border: none;
  border-radius: 0;
  padding: 0;
  position: relative;
  overflow: visible;
}
.hd-services-grid {
  margin-top: 48px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  position: relative;
  z-index: 2;
}
.hd-svc-item {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 18px;
  padding: 32px 28px;
  text-decoration: none;
  color: inherit;
  text-align: left;
  border: none;
/*   cursor: pointer; */
  position: relative;
  transition: background 0.35s ease;
}
.hd-svc-item::after {
  content: "";
  position: absolute;
  inset: -1px;
  border: 1.5px solid transparent;
  border-radius: 16px;
  pointer-events: none;
  transition:
    border-color 0.35s ease,
    box-shadow 0.35s ease;
  z-index: 2;
}
.hd-svc-item:hover {
  background: rgba(236, 28, 36, 0.04);
}
.hd-svc-item:hover::after {
  border-color: rgba(236, 28, 36, 0.45);
  box-shadow: 0 0 24px -8px rgba(236, 28, 36, 0.2);
}
.hd-svc-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  display: grid;
  place-items: center;
  flex-shrink: 0;
  transition: all 0.35s ease;
}
.hd-svc-item:hover .hd-svc-icon {
  background: rgba(236, 28, 36, 0.1);
  border-color: rgba(236, 28, 36, 0.3);
}
.hd-svc-icon-img {
  width: 22px;
  height: 22px;
  object-fit: contain;
  opacity: 0.55;
  transition: opacity 0.3s ease;
}
.hd-svc-item:hover .hd-svc-icon-img {
  opacity: 1;
}
.hd-svc-text {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.hd-svc-title, .hd-svc-title a {
  font-size: 18px;
  font-weight: 600;
  color: #ffffff;
  line-height: 1.3;
  letter-spacing: -0.01em;
  margin-bottom: 10px;
  transition: color 0.3s ease;
}
.hd-svc-item:hover .hd-svc-title , .hd-svc-item:hover .hd-svc-title a{
  color: #ec1c24;
}
.hd-svc-title a,
.hd-svc-title a:hover,
.hd-svc-title a:focus,
.hd-svc-title a:visited {
  color: inherit;
/*   text-decoration: underline !important; */
}

.hd-svc-desc {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.5);
  line-height: 1.6;
}
.hd-svc-desc a {
  color: rgba(255, 255, 255, 0.5);
  text-decoration: underline !important;
}
.hd-svc-desc a:hover {
  color: rgba(255, 255, 255, 0.8);
}
@media (max-width: 1280px) {
  .hd-svc-item {
    padding: 28px 22px;
  }
}

@media (max-width: 1024px) {
  .hd-services-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .hd-svc-item:nth-child(3n + 2) {
    border-left: 0;
    border-right: 0;
  }
  .hd-svc-item:nth-child(even) {
    border-left: 1px solid rgba(255, 255, 255, 0.06);
  }
  .hd-svc-item:nth-child(n + 3) {
    border-top: 1px solid rgba(255, 255, 255, 0.06);
  }
}
@media (max-width: 640px) {
  .hd-services-grid {
    grid-template-columns: 1fr;
  }
  .hd-svc-item {
    border: none !important;
  }
  .hd-services {
    padding: 60px 20px;
  }
}

/* ============================================================
   HD. Role Stack (hd_roles)
   ============================================================ */
.hd-roles {
  background: #000;
  padding: 80px 48px;
}
.hd-roles-filters {
  display: flex;
  gap: 10px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.hd-roles-filter {
  padding: 10px 22px;
  border-radius: 100px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: transparent;
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition:
    background 0.2s,
    color 0.2s,
    border-color 0.2s;
}
.hd-roles-filter.active,
.hd-roles-filter:hover {
  background: #ec1c24;
  border-color: #ec1c24;
  color: #fff;
  box-shadow: 0 0 24px rgba(236, 28, 36, 0.45);
}
.hd-roles-shell {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 40px;
  align-items: start;
}
.hd-roles-list-wrap {
  min-width: 0;
}
.hd-roles-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 480px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.15) transparent;
}
.hd-roles-list::-webkit-scrollbar {
  width: 4px;
}
.hd-roles-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 2px;
}
.hd-role-tab {
	position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  padding: 13px 18px 13px 12px;
  border-radius: 10px;
  border: 1px solid transparent;
  background: transparent;
  color: rgba(255, 255, 255, 0.55);
  font-size: 0.9rem;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: all 0.2s;
}
.hd-role-tab span {
  flex: 1; padding-left : 2px
}
.hd-role-tab.active,
.hd-role-tab:hover {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.1);border-color: transparent;
  color: #ffffff;
}
.hd-role-tab.active {
  background: rgba(236, 28, 36, 0.15);
  color: #fff;
}
.hd-role-tab.active::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 1.6em;
  border-radius: 2px;
  background: #ec1c24;
}
.hd-roles-stage {
  position: relative;
  height: 440px;
  perspective: 1200px;
}
.hd-role-card {
  position: absolute;
  inset: 0;
  display: flex;
  border-radius: 16px;
  overflow: hidden;
  background: #111;
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition:
    transform 0.45s cubic-bezier(0.4, 0, 0.2, 1),
    opacity 0.45s cubic-bezier(0.4, 0, 0.2, 1),
    z-index 0s 0.22s;
}
.hd-role-card.front {
  transform: translateZ(0) scale(1);
  opacity: 1;
  z-index: 10;
  pointer-events: all;
}
.hd-role-card.behind-1 {
  transform: translateY(18px) translateZ(-60px) scale(0.95);
  opacity: 0.65;
  z-index: 5;
  pointer-events: none;
}
.hd-role-card.behind-2 {
  transform: translateY(32px) translateZ(-120px) scale(0.9);
  opacity: 0.35;
  z-index: 2;
  pointer-events: none;
}
.hd-role-card.hidden {
  transform: translateY(48px) translateZ(-180px) scale(0.85);
  opacity: 0;
  z-index: 0;
  pointer-events: none;
}
.hd-role-card-img {
  width: 45%;
  flex-shrink: 0;
  background-size: cover;
  background-position: center top;
  background-color: #1a1a1a;
}
.hd-role-card-body {
  flex: 1;
  padding: 36px 32px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
  overflow-y: auto;
	justify-content: center;
}
.hd-role-card-title {
font-size: 2rem;
  font-weight: 700;
  color: #ffffff;
  line-height: 1.3;
}
.hd-role-card-desc {
  font-size: 0.9rem;
  color: rgba(255, 255, 255, 0.6);
  line-height: 1.7;
}
.hd-role-card-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.hd-role-card-tag {
  padding: 5px 12px;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 500;
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.12);
}
a.hd-role-card-tag,
a.hd-role-card-tag:hover,
a.hd-role-card-tag:focus,
a.hd-role-card-tag:active,
a.hd-role-card-tag:visited {
  color: rgba(255, 255, 255, 0.85);
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  font-size: 0.75rem;
  font-weight: 500;
  text-decoration: none;
}
.hd-role-card-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #ffffff;
  font-size: 0.9rem;
  font-weight: 600;
  text-decoration: none;
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: 100px;
  background: transparent;
  cursor: pointer;
  padding: 12px 26px;
  margin-top: 10px;
  align-self: flex-end;
  transition:
    background 0.2s,
    border-color 0.2s,
    color 0.2s;
}
.hd-role-card-link:hover {
  background: #ffffff;
  border-color: #ffffff;
  color: #111111;
}
