@media (max-width: 480px) {
  .hd-roles {
       padding: 56px 20px; 
  }
  .hd-roles-stage {
    height: 380px;
  }
  .hd-role-card-body {
    padding: 24px 20px;
  }
  .hd-role-card-title {
    font-size: 1.1rem;
  }
}

/* ============================================================
   HD. Vetting Pipeline (hd_vetting)
   ============================================================ */
.hd-vetting {
  background: #111111;
  padding: 90px 48px;
}
.hd-vetting-badge {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  letter-spacing: 0.04em;
  font-weight: 600;
  color: #ec1c24;
  background: rgba(236, 28, 36, 0.1);
  border: 1px solid rgba(236, 28, 36, 0.3);
  padding: 8px 16px;
  border-radius: 100px;
  margin-top: 24px;
}
.hd-vetting-badge::before {
  content: "";
  width: 8px;
  height: 8px;
  background: #ec1c24;
  border-radius: 50%;
  box-shadow: 0 0 10px rgba(236, 28, 36, 0.8);
  animation: hdPulse 1.8s ease-in-out infinite;
}
@keyframes hdPulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.55;
    transform: scale(1.35);
  }
}
.vp-variant-area {
  margin-top: 40px;
}
@keyframes vpAreaIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.vp-check {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.8);
  background: rgba(236, 28, 36, 0.08);
  border: 1px solid rgba(236, 28, 36, 0.22);
  padding: 6px 12px;
  border-radius: 100px;
}
.vp-check-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ec1c24;
  box-shadow: 0 0 6px rgba(236, 28, 36, 0.6);
  flex-shrink: 0;
}
.vs-shell {
  display: flex;
  flex-direction: column;
  gap: 36px;
}
.vs-pipeline {
  position: relative;
  padding: 80px 20px 0;
}
.vs-track {
  position: absolute;
  top: 42px;
  left: 48px;
  right: 48px;
  height: 2px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 2px;
}
.vs-track-fill {
  height: 100%;
  background: #ec1c24;
  border-radius: 2px;
  box-shadow: 0 0 8px rgba(236, 28, 36, 0.5);
  transition: width 0.9s cubic-bezier(0.25, 0.9, 0.3, 1.05);
}

.vs-rider {
  position: absolute;
  top: -8px;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px 8px 8px;
  background: linear-gradient(135deg, #1a1718 0%, #0f0d0e 100%);
  border: 1px solid rgba(236, 28, 36, 0.4);
  border-radius: 999px;
  box-shadow:
    0 0 0 1px rgba(236, 28, 36, 0.12),
    0 16px 32px -12px rgba(236, 28, 36, 0.45);
  white-space: nowrap;
  left: calc(var(--vs-step, 0) * (100% - 96px) / 5 + 20px);
  /* Progressive self-width shift: keeps the card's right edge inside the
     pipeline at the final steps (100% here = the card's own width). */
  transform: translateX(calc(var(--vs-step, 0) / 5 * (56px - 100%)));
  transition:
    left 0.9s cubic-bezier(0.25, 0.9, 0.3, 1.05),
    transform 0.9s cubic-bezier(0.25, 0.9, 0.3, 1.05);
}
.vs-rider-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid #ec1c24;
  flex-shrink: 0;
}
.vs-rider-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.vs-rider-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.vs-rider-name {
  font-size: 11px;
  font-weight: 600;
  color: #fff;
}
.vs-rider-status {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #ec1c24;
  animation: vpFadeUp 0.35s ease;
}
@keyframes vpFadeUp {
  from {
    opacity: 0;
    transform: translateY(3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.vs-scan-beam {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  pointer-events: none;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(236, 28, 36, 0.15) 40%,
    rgba(236, 28, 36, 0.3) 50%,
    rgba(236, 28, 36, 0.15) 60%,
    transparent 100%
  );
  background-size: 200% 100%;
  animation: vsScanBeam 1.4s ease-in-out infinite;
}
@keyframes vsScanBeam {
  from {
    background-position: -100% 0;
  }
  to {
    background-position: 200% 0;
  }
}
.vs-stations {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 0;
  position: relative;
  z-index: 5;
}
.vs-station {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 4px 0;
	 cursor: pointer;
}
.vs-station-post {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: #231f20;
  border: 2px solid rgba(255, 255, 255, 0.1);
  display: grid;
  place-items: center;
  color: rgba(255, 255, 255, 0.4);
  position: relative;
  transition: all 0.5s ease;
}
.vs-station-post svg {
  width: 26px;
  height: 26px;
}
.vs-station.is-past .vs-station-post {
  border-color: rgba(236, 28, 36, 0.45);
  color: #ec1c24;
  background: rgba(236, 28, 36, 0.06);
}
.vs-station.is-curr .vs-station-post {
  border-color: #ec1c24;
  color: #fff;
  background: rgba(236, 28, 36, 0.14);
  box-shadow:
    0 0 0 5px rgba(236, 28, 36, 0.12),
    0 0 20px rgba(236, 28, 36, 0.35);
}
.vs-station-seal {
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 2px solid #ec1c24;
  opacity: 0.4;
  animation: hdPulse 2.5s ease-in-out infinite;
}
.vs-station-label {
  font-size: 13px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.6);
  text-align: center;
}
/* Phone-only inline copy of the step detail (shown ≤560px under the
   active station); desktop/tablet keep the bottom .vs-detail panel. */
.vs-station-inline-detail {
  display: none;
}

.vs-station.is-curr .vs-station-label {
  color: #fff;
  font-weight: 700;
}
.vs-station.is-past .vs-station-label {
  color: rgba(255, 255, 255, 0.75);
}
.vs-bottom {
  display: grid;
  grid-template-columns: 1fr 220px;
  gap: 32px;
  align-items: start;
}
.vs-detail {
  animation: vpAreaIn 0.35s ease;
}
.vs-detail-tag {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #ec1c24;
  margin-bottom: 14px;
}
.vs-detail-desc {
  font-size: 16px;
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.78);
  margin-bottom: 20px;
}
.vs-detail-checks {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.vs-stamps {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  padding: 24px 20px;
}
.vs-stamps-label {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.65);
  margin-bottom: 14px;
}
.vs-stamps-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.vs-stamp {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  display: grid;
  place-items: center;
  color: rgba(255, 255, 255, 0.35);
  transition: all 0.4s ease;
}
.vs-stamp svg {
  width: 20px;
  height: 20px;
}
.vs-stamp.is-earned {
  background: rgba(236, 28, 36, 0.1);
  border-color: rgba(236, 28, 36, 0.35);
  color: #ec1c24;
  box-shadow: 0 0 8px rgba(236, 28, 36, 0.3);
}
.vs-approved-badge {
  margin-top: 14px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #ec1c24;
  background: rgba(236, 28, 36, 0.12);
  border: 1px solid rgba(236, 28, 36, 0.35);
  padding: 5px 10px;
  border-radius: 100px;
}
.vs-approved-badge svg {
  width: 12px;
  height: 12px;
}
@media (max-width: 900px) {
  .vs-bottom {
    grid-template-columns: 1fr;
  }
  .vs-rider {
    display: none;
  }
  .vs-pipeline {
    padding-top: 0;
  }
  .vs-stations {
    grid-template-columns: repeat(3, 1fr);
    row-gap: 16px;
  }
}
@media (max-width: 560px) {
  .vs-stations {
/*     grid-template-columns: repeat(2, 1fr); */
  }
  .hd-vetting {
    padding: 60px 20px;
  }
	/* Rider becomes a static pill at the top (hidden by the 900px rules).
     Stays position: relative so the absolute .vs-scan-beam anchors to the
     pill, not the pipeline. */
  .vs-rider {
    display: flex;
    position: relative;
    top: auto;
    left: auto;
    transform: none;
    width: fit-content;
    margin-bottom: 28px;
  }
  .vs-pipeline {
    padding: 0;
  }
  .vs-track {
    display: none;
  }
  /* Vertical timeline: icon circle left, title right. */
  .vs-stations {
    grid-template-columns: 1fr;
    row-gap: 32px;
    padding: 0 30px;
  }
  .vs-station {
    flex-direction: row;
    align-items: center;
    flex-wrap: wrap;
    gap: 20px;
    text-align: left;
    position: relative;
  }
  .vs-station.is-curr .vs-station-inline-detail {
    display: block;
    flex-basis: 100%;
    margin: 10px 0 0 0px;
    cursor: default;
  }
  .vs-bottom .vs-detail {
    display: none;
  }
  .vs-station-label {
    font-size: 15px;
    font-weight: 700;
    text-align: left;
  }
  /* Dotted connector between circles. */
  .vs-station:not(:last-child)::after {
    content: "";
    position: absolute;
    left: 27px;
    top: 64px;
    height: 24px;
    border-left: 2px dotted rgba(255, 255, 255, 0.18);
  }
}

/* ============================================================
   HD. Engagement Models (hd_engage)
   ============================================================ */
.hd-engage-v2 {
  background: #0a0a0a;
  padding: 90px 48px;
}
.hd-ev-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr);
  gap: 56px;
  margin-top: 64px;
  align-items: start;
}
.hd-ev-accordion {
  display: flex;
  flex-direction: column;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}
.hd-ev-row {
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}
.hd-ev-row-head {
  width: 100%;
  display: grid;
  grid-template-columns: 48px 1fr 36px;
  align-items: center;
  gap: 16px;
  padding: 24px 4px;
  background: none;
  border: 0;
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  transition: padding 0.4s cubic-bezier(0.18, 1.2, 0.3, 1);
}
.hd-ev-row.is-open .hd-ev-row-head {
  padding-bottom: 18px;
}
/* WCAG AA contrast for this accordion's ordinals.
   Unlike the homepage equivalent (.engage-v3 .ev-row-num, 32px), this text is 13px —
   below the 18.66px-bold "large text" cutoff — so it needs 4.5:1, not 3:1. Both states
   were failing against the .hd-engage-v2 backdrop of #0a0a0a:
     inactive  rgba(255,255,255,.35) composites to #606060 = 3.15:1
     active    #ec1c24                                     = 4.49:1  (misses by 0.01)
   Raised to .50 (-> #848484, 5.29:1) and #ef2d34 (4.80:1). #ef2d34 is the smallest
   lift off the brand red that clears the threshold here, so the shift stays subtle.
   #ec1c24 is deliberately left untouched elsewhere: it only fails at this small size
   (it is 4.41:1 on white), and a global brand-red change is not warranted. */
.hd-ev-row-num {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: rgba(255, 255, 255, 0.5);
  transition:
    color 0.45s ease,
    transform 0.45s ease;
}
.hd-ev-row.is-open .hd-ev-row-num {
  color: #ef2d34;
  transform: translateX(2px);
}
.hd-ev-row-head:hover .hd-ev-row-num {
  color: #ef2d34;
}
.hd-ev-row-title {
  font-size: 24px;
  line-height: 1.15;
  font-weight: 600;
  color: #fff;
  letter-spacing: -0.015em;
}
.hd-ev-row-chev {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: rgba(255, 255, 255, 0.5);
  transition:
    transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1),
    background 0.4s ease,
    color 0.4s ease,
    border-color 0.4s ease;
}
.hd-ev-row.is-open .hd-ev-row-chev {
  transform: rotate(180deg);
  background: #ec1c24;
  border-color: #ec1c24;
  color: #fff;
}
.hd-ev-row-body {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.55s cubic-bezier(0.18, 1.2, 0.3, 1);
}
.hd-ev-row.is-open .hd-ev-row-body {
  grid-template-rows: 1fr;
}
.hd-ev-row-body-inner {
  overflow: hidden;
  padding-left: 64px;
  padding-right: 4px;
}
.hd-ev-row.is-open .hd-ev-row-body-inner {
  padding-bottom: 28px;
}
.hd-ev-row-desc {
  color: rgba(255, 255, 255, 0.7);
  font-size: 15px;
  line-height: 1.6;
  margin-bottom: 18px;
  max-width: 480px;
}
.hd-ev-row-bullets {
  list-style: none;
  margin: 0 0 18px;
  padding: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 24px;
}
.hd-ev-row-bullets li {
  color: #fff;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13.5px;
  font-weight: 500;
}
.hd-ev-bullet-dot {
  flex: none;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #ec1c24;
}
.hd-ev-row-best {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.55);
  margin-bottom: 18px;
  line-height: 1.5;
}
.hd-ev-row-best strong {
  color: rgba(255, 255, 255, 0.8);
}
.hd-ev-row-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 6px;
  color: #fff !important;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  font-family: inherit;
  transition:
    background 0.3s ease,
    transform 0.3s ease;
}
.hd-ev-row-cta:hover {
  background: #ec1c24;
  border-color: #ec1c24;
  transform: translateY(-1px);
}
.hd-ev-row-cta span {
  transition: transform 0.3s ease;
}
.hd-ev-row-cta:hover span {
  transform: translateX(3px);
}
.hd-ev-stage {
  position: sticky;
  top: 24px;
}
.hd-ev-stage-frame {
  position: relative;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 20px;
  min-height: 400px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: hdEvFadeIn 0.5s ease;
}
@keyframes hdEvFadeIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.hd-ev-stage-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.hd-ev-stage-num {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #ec1c24;
}
.hd-ev-stage-title {
  color: #fff;
  font-size: 15px;
  font-weight: 600;
}
.hd-ev-svg {
  width: 100%;
  height: 100%;
  flex: 1;
  min-height: 320px;
  display: block;
}
.hd-ev-pop {
  animation: hdEvPop 0.5s ease forwards;
  animation-delay: var(--d, 0s);
}
@keyframes hdEvPop {
  from {
    opacity: 0;
    transform: scale(0.6);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
.hd-ev-bar-fill {
  animation: hdEvBarGrow 1.2s ease forwards;
  animation-delay: 0.6s;
}
@keyframes hdEvBarGrow {
  from {
    width: 0;
  }
  to {
    width: 280px;
  }
}
@media (max-width: 1024px) {
  .hd-ev-layout {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .hd-ev-stage {
    position: static;
  }
}
@media (max-width: 640px) {
	
	/* Zoom the stage illustration — 480×320 viewBox renders too small on
     phone-width frames. Edge margins in the artwork absorb the crop. */
   
  .hd-ev-row-bullets {
    grid-template-columns: 1fr;
  }
  .hd-ev-row-body-inner {
    padding-left: 16px;
  }
  .hd-ev-row-head {
    grid-template-columns: 36px 1fr 32px;
    gap: 10px;
  }
  .hd-ev-row-title {
    font-size: 20px;
  }
  .hd-engage-v2 {
    padding: 60px 20px;
  }
}

/* ============================================================
   HD. Tech Stacks (hd_tech)
   ============================================================ */
.hd-tt2 {
  background: #111111;
  padding: 100px 48px;
}
.hd-tt2 .container {
  max-width: 1240px;
  margin: 0 auto;
}
.hd-tt2 .section-intro {
  margin-bottom: 0;
  flex: 1 1 480px;
  max-width: 620px;
  text-align: left;
}
.hd-tt2 .eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #ec1c24;
  margin-bottom: 16px;
}
.hd-tt2 .section-intro h2 {
  font-size: clamp(30px, 3.2vw, 44px);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: #fff;
  margin: 0;
}
.hd-tt2 .sv-tools-head > p {
  color: rgba(255, 255, 255, 0.6);
  font-size: 16px;
  line-height: 1.6;
  flex: 1 1 340px;
  max-width: 440px;
  text-align: left;
  margin: 0;
}
.hd-tt2 .sv-tools-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 40px;
  flex-wrap: wrap;
  margin-bottom: 36px;
}
.hd-tt2 .sv-tabs {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-bottom: 40px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding-bottom: 18px;
}
.hd-tt2 .sv-tab {
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.6);
  padding: 10px 18px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: transparent;
  cursor: pointer;
  transition: all 0.2s ease;
}
.hd-tt2 .sv-tab:hover {
  color: #fff;
  border-color: rgba(255, 255, 255, 0.18);
}
.hd-tt2 .sv-tab.is-active {
  color: #fff;
  background: #ec1c24;
  border-color: #ec1c24;
}
.hd-tt2-cat-desc {
  color: rgba(255, 255, 255, 0.6);
  font-size: 15px;
  line-height: 1.6;
  max-width: 720px;
  margin: 0 0 28px;
  animation: svFade 0.4s ease both;
}
@keyframes svFade {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.hd-tt2 .sv-tools-grid {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  grid-template-columns: none;
