/* ── HD. Why Hire With Us (hd_why) ─────────────────────────────── */
.hd-why {
  background: #0a0a0a;
  padding: 90px 48px;
}
.hd-why-stage {
  margin-top: 72px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr) minmax(0, 1fr);
  gap: 28px;
  align-items: center;
}
.hd-why-col {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.hd-why-card {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 18px;
  padding: 26px 24px;
  transition: all 0.35s ease;
  cursor: pointer;
}
.hd-why-card:hover {
  border-color: rgba(236, 28, 36, 0.4);
  transform: translateY(-3px);
  box-shadow: 0 18px 40px -20px rgba(236, 28, 36, 0.35);
}
.hd-why-icon {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: rgba(236, 28, 36, 0.1);
  border: 1px solid rgba(236, 28, 36, 0.25);
  display: grid;
  place-items: center;
  margin-bottom: 16px;
  transition: all 0.3s ease;
}
.hd-why-icon img {
  width: 18px;
  height: 18px;
  object-fit: contain;
  display: block;
  filter: brightness(0) invert(1);
  opacity: 0.85;
  transition: opacity 0.3s ease;
}
.hd-why-card:hover .hd-why-icon {
  background: rgba(236, 28, 36, 0.2);
  box-shadow: 0 0 12px rgba(236, 28, 36, 0.5);
}
.hd-why-card:hover .hd-why-icon img {
  opacity: 1;
}
.hd-why-card h4 {
  font-size: 17px;
  font-weight: 600;
  color: #fff;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
  line-height: 1.3;
}
	 .hd-why-card h3 { 
  font-size: 17px;
  font-weight: 600;
  color: #fff;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
  line-height: 1.3;
}
.hd-why-card p {
  font-size: 13.5px;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.6);
  margin: 0;
}
/* Center image column */
.hd-why-center {
  position: relative;
  aspect-ratio: 1 / 1.02;
  display: grid;
  place-items: center;
}
@keyframes hdWhySpin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes hdWhySpinRev {
  to {
    transform: rotate(-360deg);
  }
}
.hd-why-ring {
  position: absolute;
  inset: 4%;
  border-radius: 50%;
  border: 1px dashed rgba(255, 255, 255, 0.1);
  animation: hdWhySpin 80s linear infinite;
  pointer-events: none;
}
.hd-why-ring.inner {
  inset: 14%;
  border-color: rgba(236, 28, 36, 0.15);
  animation: hdWhySpinRev 60s linear infinite;
}
.hd-why-mask {
  position: relative;
  width: 78%;
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow:
    0 0 80px rgba(236, 28, 36, 0.25),
    inset 0 0 60px rgba(236, 28, 36, 0.15);
}
.hd-why-mask > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  filter: grayscale(0.3) contrast(1.05) brightness(0.85);
}
.hd-why-mask::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle, transparent 40%, rgba(0, 0, 0, 0.5) 100%);
  pointer-events: none;
}
.hd-why-mask-logo {
  position: absolute;
  bottom: 16%;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  padding: 10px 20px;
  border-radius: 100px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  z-index: 2;
  white-space: nowrap;
}
.hd-why-mask-logo img {
  height: 22px;
  width: auto;
  display: block;
}
/* Responsive */
@media (max-width: 1100px) {
  .hd-why {
    padding: 70px 32px;
  }
  .hd-why-stage {
    grid-template-columns: 1fr;
    gap: 48px;
  }
  .hd-why-col {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
  }
  .hd-why-center {
    order: -1;
    max-width: 360px;
    width: 100%;
    margin: 0 auto;
  }
}
@media (max-width: 640px) {
  .hd-why {
    padding: 60px 20px;
  }
  .hd-why-col {
    grid-template-columns: 1fr;
  }
  .hd-why-center {
    max-width: 300px;
  }
}

/* ── HD. Hiring Process (hd_process) ─────────────────────────── */
.hd-process {
  background: #111111;
  padding: 90px 48px;
}
/* Centered section header */
.hd-process-head {
  max-width: 720px;
  margin: 0 auto 64px;
  text-align: center;
}
.hd-process-head .hd-eyebrow {
  justify-content: center;
}
.hd-process-head .hd-h2,
.hd-process-head .hd-sub {
  margin-left: auto;
  margin-right: auto;
}
.hd-process-head .hd-sub {
  margin-top: 18px;
  color: rgba(255, 255, 255, 0.6);
}
/* Two-column layout */
.hd-process-ref-layout {
  display: grid;
  grid-template-columns: 420px 1fr;
  gap: 60px;
  align-items: center;
  max-width: 1200px;
  margin: 0 auto;
}
.hd-process-ref-left {
  display: flex;
  align-items: center;
  justify-content: center;
}
/* Orbit wrapper */
.hd-orbit-wrapper {
  position: relative;
  width: 420px;
  height: 420px;
  max-width: 100%;
}
.hd-orbit-svg {
  width: 100%;
  height: 100%;
  transition: transform 1.2s cubic-bezier(0.4, 0, 0.2, 1);
}
/* Orbit center circle */
.hd-orbit-center {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 175px;
  height: 175px;
  border-radius: 50%;
  background: #0a0a0a;
  border: 2px solid rgba(255, 255, 255, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow:
    0 0 0 14px rgba(17, 17, 17, 1),
    0 0 0 15px rgba(255, 255, 255, 0.04),
    0 0 60px 10px rgba(236, 28, 36, 0.06);
  z-index: 3;
}
.hd-orbit-center-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 18px;
  text-align: center;
}
.hd-orbit-center-step {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #ec1c24;
}
.hd-orbit-center-title {
  font-size: 17px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.01em;
  line-height: 1.2;
}
/* Steps list */
.hd-process-ref-right {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.hd-process-ref-step {
  display: grid;
  grid-template-columns: 70px 48px 1fr;
  gap: 0 16px;
  align-items: start;
  padding: 18px 16px;
  border-radius: 16px;
  cursor: pointer;
  transition: all 0.45s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  opacity: 0.45;
}
.hd-process-ref-step.is-active {
  opacity: 1;
  background: rgba(255, 255, 255, 0.03);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.06);
}
.hd-process-ref-step.is-past {
  opacity: 0.6;
}
.hd-process-ref-step:not(.is-active):hover {
  opacity: 0.7;
}
/* Part label */
.hd-process-ref-part {
  font-size: 14px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.45);
  padding-top: 12px;
  transition: color 0.4s ease;
  white-space: nowrap;
}
.hd-process-ref-step.is-active .hd-process-ref-part {
  color: rgba(255, 255, 255, 0.7);
}
.hd-process-ref-step.is-past .hd-process-ref-part {
  color: #ec1c24;
}
/* Icon circle */
.hd-process-ref-icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: #1a1a1a;
  border: 1.5px solid rgba(255, 255, 255, 0.08);
  display: grid;
  place-items: center;
  margin-top: 4px;
  flex-shrink: 0;
  transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.hd-process-ref-icon img {
  width: 18px;
  height: 18px;
  object-fit: contain;
  display: block;
  filter: brightness(0) invert(1);
  opacity: 0.4;
  transition: opacity 0.5s ease;
}
.hd-process-ref-step.is-active .hd-process-ref-icon {
  background: #ec1c24;
  border-color: #ec1c24;
  transform: scale(1.15);
  box-shadow:
    0 0 0 5px rgba(236, 28, 36, 0.15),
    0 6px 20px -4px rgba(236, 28, 36, 0.5);
}
.hd-process-ref-step.is-active .hd-process-ref-icon img {
  opacity: 1;
}
.hd-process-ref-step.is-past .hd-process-ref-icon {
  background: #2a1518;
  border-color: rgba(236, 28, 36, 0.4);
}
.hd-process-ref-step.is-past .hd-process-ref-icon img {
  opacity: 0.7;
}
/* Content */
.hd-process-ref-content {
  padding-top: 2px;
  transition: transform 0.4s ease;
}
.hd-process-ref-step.is-active .hd-process-ref-content {
  transform: translateX(4px);
}
.hd-process-ref-title {
  font-size: 18px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.65);
  letter-spacing: -0.02em;
  line-height: 1.2;
  margin-bottom: 6px;
  transition:
    font-size 0.4s ease,
    color 0.4s ease;
}
.hd-process-ref-step.is-active .hd-process-ref-title {
  font-size: 20px;
  color: #fff;
}
.hd-process-ref-desc {
  font-size: 14px;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.5);
  max-width: 480px;
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  transition:
    max-height 0.5s cubic-bezier(0.4, 0, 0.2, 1),
    opacity 0.4s ease;
}
.hd-process-ref-step.is-active .hd-process-ref-desc {
  max-height: 120px;
  opacity: 1;
}
/* Responsive */
@media (max-width: 1100px) {
  .hd-process {
    padding: 70px 32px;
  }
  .hd-process-ref-layout {
    grid-template-columns: 1fr;
    gap: 48px;
  }
  .hd-orbit-wrapper {
    width: 320px;
    height: 320px;
  }
  .hd-process-ref-left {
    width: 100%;
  }
  .hd-orbit-center {
    width: 140px;
    height: 140px;
  }
  .hd-orbit-center-title {
    font-size: 14px;
  }
}
@media (max-width: 640px) {
  .hd-process {
    padding: 60px 20px;
  }
  .hd-orbit-wrapper {
    width: 260px;
    height: 260px;
  }
  .hd-orbit-center {
    width: 110px;
    height: 110px;
  }
  .hd-orbit-center-title {
    font-size: 12px;
  }
  .hd-process-ref-step {
    grid-template-columns: 48px 40px 1fr;
    gap: 0 10px;
  }
  .hd-process-ref-part {
    font-size: 12px;
  }
  .hd-process-head {
    margin-bottom: 40px;
  }
}

/* ── HD. Comparison (hd_compare) ──────────────────────────────────── */
.hd-compare {
  background: #0a0a0a;
  padding: 90px 48px;
}
.hd-compare-filters {
  margin-top: 36px;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
}
.hd-chip {
  font-size: 13px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.65);
  background: #231f20;
  border: 1px solid rgba(255, 255, 255, 0.08);
  padding: 9px 16px;
  border-radius: 100px;
