  transition: all 0.25s ease;
}
.hd-chip:hover {
  color: #fff;
  border-color: rgba(255, 255, 255, 0.14);
}
.hd-chip.active {
  background: #ec1c24;
  border-color: #ec1c24;
  color: #fff;
  box-shadow: 0 6px 20px -8px rgba(236, 28, 36, 0.6);
}
.hd-compare-table {
  margin-top: 36px;
  background: #231f20;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 22px;
  overflow: hidden;
  position: relative;
}
.hd-compare-row {
  display: grid;
  grid-template-columns: 1.1fr 1.4fr 1.2fr 1.2fr;
  align-items: stretch;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  transition: background 0.3s ease;
}
.hd-compare-row:last-child {
  border-bottom: 0;
}
.hd-compare-row.head {
  background: rgba(255, 255, 255, 0.02);
  font-size: 12px;
  letter-spacing: 0.02em;
