}
.hd-compare-cell:last-child {
  border-right: 0;
}
.hd-compare-cell.factor {
  font-weight: 600;
  color: #fff;
}
.hd-compare-cell.tb {
  background: linear-gradient(
    180deg,
    rgba(236, 28, 36, 0.06) 0%,
    rgba(236, 28, 36, 0.02) 100%
  );
  border-left: 1px solid rgba(236, 28, 36, 0.3);
  border-right: 1px solid rgba(236, 28, 36, 0.3);
  position: relative;
}
.hd-compare-row.head .hd-compare-cell.tb {
  background: linear-gradient(
    180deg,
    rgba(236, 28, 36, 0.12) 0%,
    rgba(236, 28, 36, 0.04) 100%
  );
  color: #fff;
}
.hd-mark {
  display: inline-block;
  width: 22px;
  text-align: center;
  font-weight: 700;
  margin-right: 6px;
}
.hd-mark.pos {
  color: #29d27d;
}
.hd-mark.neu {
  color: #ffb54d;
}
.hd-mark.neg {
  color: #ec1c24;
}
@media (max-width: 900px) {
  .hd-compare {
    padding: 70px 32px;
  }
  .hd-compare-row {
    grid-template-columns: 1fr;
  }
  .hd-compare-row.head {
    display: none;
  }
  .hd-compare-cell {
    border-right: 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    padding: 16px;
  }
  .hd-compare-cell::before {
    content: attr(data-col);
    display: block;
    font-size: 10px;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.45);
