@media (max-width: 640px) {
  .hd-compare {
    padding: 60px 20px;
  }
}

/* ── HD. Industry Experts (hd_experts) ────────────────────────────── */
.hd-experts {
  background: #111111;
  padding: 90px 48px;
  position: relative;
  overflow: hidden;
}
.hd-experts-glow {
  position: absolute;
  pointer-events: none;
  width: 800px;
  height: 800px;
  left: 50%;
  top: 60%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgba(236, 28, 36, 0.07) 0%,
    rgba(236, 28, 36, 0.02) 40%,
    transparent 65%
  );
