  display: flex;
  gap: 14px;
  height: 480px;
  align-items: stretch;
}
.hd-strip-card {
  flex: 0.55 1 0%;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
