  flex-direction: column;
  position: relative;
}
.hd-strip-card.is-active {
  flex: 2.2 1 0%;
  background: #0e1118;
  border-color: rgba(236, 28, 36, 0.35);
  flex-direction: row;
  box-shadow: 0 24px 64px -24px rgba(236, 28, 36, 0.2);
}
.hd-strip-card:not(.is-active):hover {
  border-color: rgba(255, 255, 255, 0.14);
  box-shadow: 0 16px 40px -20px rgba(0, 0, 0, 0.5);
}
.hd-strip-card-img {
