  overflow: hidden;
  background: #0a0d14;
  transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}
.hd-strip-card:not(.is-active) .hd-strip-card-img {
  height: 100%;
  flex: 1 1 0%;
  min-height: 0;
}
.hd-strip-card.is-active .hd-strip-card-img {
