.hd-strip-card:not(.is-active) .hd-strip-card-img img {
  filter: saturate(0.55) brightness(0.7);
}
.hd-strip-card.is-active .hd-strip-card-img img {
  filter: saturate(0.9) contrast(1.05);
}
.hd-strip-card:hover .hd-strip-card-img img {
  transform: scale(1.04);
}
.hd-strip-card-img-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}
.hd-strip-card.is-active .hd-strip-card-img-overlay {
  background:
    linear-gradient(180deg, transparent 40%, rgba(5, 7, 11, 0.45) 100%),
    linear-gradient(90deg, transparent 55%, rgba(14, 17, 24, 0.75) 100%);
}
.hd-strip-card:not(.is-active) .hd-strip-card-img-overlay {
  background: linear-gradient(
    180deg,
    transparent 30%,
    rgba(5, 7, 11, 0.7) 100%
  );
}
.hd-strip-card-indicator {
  position: absolute;
  top: 16px;
  left: 16px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #fff;
  background: rgba(0, 0, 0, 0.55);
  border: 1px solid rgba(236, 28, 36, 0.35);
  padding: 6px 12px;
  border-radius: 100px;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  z-index: 3;
  opacity: 0;
  transform: translateY(-6px);
  transition:
    opacity 0.35s ease 0.15s,
    transform 0.35s ease 0.15s;
}
.hd-strip-card.is-active .hd-strip-card-indicator {
  opacity: 1;
  transform: translateY(0);
}
.hd-strip-indicator-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ec1c24;
  box-shadow: 0 0 10px rgba(236, 28, 36, 0.8);
  animation: hdExPulse 1.8s ease-in-out infinite;
}
@keyframes hdExPulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.6;
    transform: scale(1.3);
  }
}
.hd-strip-card-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  gap: 0;
  transition: padding 0.6s cubic-bezier(0.4, 0, 0.2, 1);
  overflow: hidden;
