/* =========================================================
   Engineering Setup Advisor (.hd-advisor)
   ========================================================= */
.hd-advisor {
  background: #0a0a0a;
  padding: 100px 48px;
}
.hd-advisor-shell {
  margin-top: 64px;
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  gap: 32px;
  align-items: stretch;
}
.hd-advisor-panel {
  background: #171717;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 22px;
  padding: 36px;
}
.hd-advisor-progress {
  display: flex;
  gap: 6px;
  margin-bottom: 28px;
}
.hd-advisor-progress span {
  flex: 1;
  height: 3px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.1);
  transition: all 0.3s ease;
}
.hd-advisor-progress span.done {
  background: #ec1c24;
}
.hd-advisor-progress span.active {
  background: linear-gradient(90deg, #ec1c24, rgba(236, 28, 36, 0.3));
}

.hd-advisor-step-label {
  font-size: 11px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #ec1c24;
  font-weight: 700;
  margin-bottom: 12px;
}
.hd-advisor-question {
  font-size: 26px;
  font-weight: 600;
  color: #fff;
  margin-bottom: 28px;
  letter-spacing: -0.015em;
  line-height: 1.2;
}
.hd-advisor-options {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.hd-advisor-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: #1e1e1e;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  font-size: 15px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.78);
  cursor: pointer;
  text-align: left;
  width: 100%;
  transition: all 0.25s ease;
}
.hd-advisor-option:hover {
  border-color: rgba(236, 28, 36, 0.4);
  color: #fff;
}
.hd-advisor-option.selected {
  background: linear-gradient(
    180deg,
    rgba(236, 28, 36, 0.12) 0%,
    rgba(236, 28, 36, 0.04) 100%
  );
  border-color: #ec1c24;
  color: #fff;
  box-shadow: 0 0 0 1px rgba(236, 28, 36, 0.25);
}
.hd-advisor-option-check {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.2);
  display: grid;
  place-items: center;
  flex-shrink: 0;
  transition: all 0.25s ease;
}
.hd-advisor-option.selected .hd-advisor-option-check {
  background: #ec1c24;
  border-color: #ec1c24;
}
.hd-advisor-option-check svg {
  width: 11px;
  height: 11px;
  color: #fff;
  opacity: 0;
}
.hd-advisor-option.selected .hd-advisor-option-check svg {
  opacity: 1;
}

.hd-advisor-other {
  margin-top: 8px;
  display: none;
}
.hd-advisor-other.is-visible {
  display: block;
}
.hd-advisor-other-label {
  display: block;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.7);
  margin-bottom: 8px;
  font-weight: 500;
}
.hd-advisor-input {
  width: 100%;
  padding: 14px 16px;
  background: #1e1e1e;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  color: #fff !important;
  font-family: inherit;
  font-size: 14.5px;
  transition: all 0.25s ease;
  resize: vertical;
  min-height: 70px;
  box-sizing: border-box;
}
.hd-advisor-input:focus {
  outline: none;
  border-color: #ec1c24;
  box-shadow: 0 0 0 3px rgba(236, 28, 36, 0.12);
}

.hd-advisor-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 28px;
  padding-top: 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.hd-advisor-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13.5px;
  color: rgba(255, 255, 255, 0.55);
  font-weight: 500;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
}
.hd-advisor-back:hover {
  color: #fff;
}
.hd-advisor-back:disabled {
  opacity: 0.3;
  cursor: default;
}
.hd-advisor-reset {
  font-size: 12.5px;
  color: rgba(255, 255, 255, 0.45);
  font-weight: 500;
  text-decoration: underline;
  text-underline-offset: 3px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
}
.hd-advisor-reset:hover {
  color: #ec1c24;
}

.hd-advisor-result {
  background: linear-gradient(180deg, #2c2425 0%, #15110f 100%);
  border: 1px solid rgba(236, 28, 36, 0.4);
  border-radius: 22px;
  padding: 44px 40px;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  min-height: 480px;
}
.hd-advisor-result::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      60% 50% at 100% 0%,
      rgba(236, 28, 36, 0.2),
      transparent 60%
    ),
    radial-gradient(50% 40% at 0% 100%, rgba(12, 35, 64, 0.3), transparent 60%);
  pointer-events: none;
}
.hd-advisor-visual {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  overflow: hidden;
  animation: hdAdvisorFadeIn 0.5s ease both;
}
@keyframes hdAdvisorFadeIn {
  from {
    opacity: 0;
    transform: scale(1.03);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
.hd-advisor-visual-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
  filter: saturate(0.75) brightness(0.6);
}
.hd-advisor-visual-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    transparent 0%,
    transparent 50%,
    rgba(10, 10, 10, 0.55) 72%,
    rgba(10, 10, 10, 0.92) 100%
  );
  pointer-events: none;
}
.hd-advisor-visual-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 32px;
  z-index: 2;
  text-align: left;
}
.hd-advisor-visual-caption {
  font-size: 22px;
  font-weight: 600;
  color: #fff;
  letter-spacing: -0.015em;
  line-height: 1.2;
  margin-bottom: 8px;
}
.hd-advisor-visual-sub {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.65);
  line-height: 1.55;
  max-width: 340px;
}
.hd-advisor-result-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  font-weight: 700;
  color: #ec1c24;
  padding: 6px 12px;
  border-radius: 100px;
  background: rgba(236, 28, 36, 0.15);
  border: 1px solid rgba(236, 28, 36, 0.4);
  position: relative;
  z-index: 2;
  align-self: center;
  margin-bottom: 18px;
}
.hd-advisor-result-badge svg {
  width: 11px;
  height: 11px;
}
.hd-advisor-result-title {
  font-size: 30px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.02em;
  margin-bottom: 14px;
  position: relative;
  z-index: 2;
}
.hd-advisor-result-desc {
  font-size: 15px;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.75);
  margin-bottom: 22px;
  max-width: 400px;
  position: relative;
  z-index: 2;
}
.hd-advisor-result-model {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
  background: #ec1c24;
  color: #fff;
  padding: 8px 14px;
  border-radius: 100px;
  align-self: center;
  margin-bottom: 22px;
  position: relative;
  z-index: 2;
  box-shadow: 0 8px 24px -8px rgba(236, 28, 36, 0.6);
}
.hd-advisor-result-model svg {
  width: 13px;
  height: 13px;
}
.hd-advisor-result-fit-label {
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.55);
  margin-bottom: 12px;
  font-weight: 600;
  position: relative;
  z-index: 2;
}
.hd-advisor-result-fit {
  list-style: none;
  padding: 0;
  margin-bottom: 28px;
  position: relative;
  z-index: 2;
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
}
.hd-advisor-result-fit li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  color: rgba(255, 255, 255, 0.8);
  padding: 6px 0;
}
.hd-advisor-result-fit li svg {
  width: 14px;
  height: 14px;
  color: #29d27d;
  flex-shrink: 0;
}
.hd-advisor-result-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: center;
  position: relative;
  z-index: 2;
  margin-top: 8px;
}
.hd-advisor-result-actions .hd-btn {
  padding: 13px 22px;
  font-size: 14px;
}
@media (max-width: 1280px) {
  .hd-advisor-panel {
    padding: 30px;
  }
  .hd-advisor-question {
    font-size: 23px;
  }
