/* ═══════════════════════════════════════════════════════════════════════════
   Service Hero Banner  (.sv-hero)
   Pixel-perfect match of Claude Design SvHero + SvServiceCircleViz.
   2-column: LEFT (hero content) | RIGHT (circle disc + radial chip items)
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Section ─────────────────────────────────────────────────────────────── */
.sv-hero {
  background: #0a0a0b;
  color: #ffffff;
  position: relative;
  overflow: hidden;
  min-height: 760px;
  padding: 0 48px;
  border-bottom: 1px solid #1a1a1d;
}

/* Radial gradient + pixel-dot particle overlay (matches .hero-network::before) */
.sv-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      900px 600px at 78% 50%,
      rgba(236, 28, 36, 0.1),
      transparent 60%
    ),
    radial-gradient(
      700px 500px at 20% 0%,
      rgba(24, 95, 165, 0.06),
      transparent 70%
    ),
    radial-gradient(
      2.5px 2.5px at 8% 18%,
      rgba(255, 90, 90, 0.85),
      transparent 60%
    ),
    radial-gradient(
      2px 2px at 22% 82%,
      rgba(255, 90, 90, 0.75),
      transparent 60%
    ),
    radial-gradient(
      3px 3px at 36% 12%,
      rgba(255, 110, 110, 0.7),
      transparent 60%
    ),
    radial-gradient(
      2px 2px at 48% 68%,
      rgba(255, 80, 80, 0.8),
      transparent 60%
    ),
    radial-gradient(
      2.5px 2.5px at 62% 26%,
      rgba(255, 100, 100, 0.7),
      transparent 60%
    ),
    radial-gradient(
      2px 2px at 74% 88%,
      rgba(255, 90, 90, 0.85),
      transparent 60%
    ),
    radial-gradient(
      3px 3px at 84% 38%,
      rgba(255, 110, 110, 0.75),
      transparent 60%
    ),
    radial-gradient(
      2px 2px at 92% 72%,
      rgba(255, 90, 90, 0.7),
      transparent 60%
    ),
    radial-gradient(
      2.5px 2.5px at 14% 56%,
      rgba(255, 100, 100, 0.65),
      transparent 60%
    ),
    radial-gradient(2px 2px at 56% 8%, rgba(255, 90, 90, 0.7), transparent 60%),
    radial-gradient(
      2px 2px at 68% 60%,
      rgba(255, 110, 110, 0.6),
      transparent 60%
    ),
    radial-gradient(
      2.5px 2.5px at 30% 40%,
      rgba(255, 90, 90, 0.55),
      transparent 60%
    );
  pointer-events: none;
  z-index: 1;
}

/* Left-side darkening overlay for text legibility over the visual */
.sv-hero::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(10, 10, 11, 0.92) 0%,
      rgba(10, 10, 11, 0.78) 22%,
      rgba(10, 10, 11, 0.45) 42%,
      rgba(10, 10, 11, 0.1) 60%,
      rgba(10, 10, 11, 0) 75%
    ),
    linear-gradient(
      180deg,
      rgba(10, 10, 11, 0.55) 0%,
      rgba(10, 10, 11, 0) 22%,
      rgba(10, 10, 11, 0) 78%,
      rgba(10, 10, 11, 0.7) 100%
    );
  pointer-events: none;
  z-index: 2;
}

/* Optional decorative background image */
.sv-hero-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  opacity: 0.12;
  pointer-events: none;
  z-index: 0;
}

/* ── 2-column grid shell ──────────────────────────────────────────────────── */
.sv-hero-wrap {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  gap: 60px;
  align-items: center;
  min-height: 760px;
  padding: 80px 0 60px;
  position: relative;
  z-index: 3;
}

/* ── LEFT column: hero content ───────────────────────────────────────────── */
.sv-hero-content {
  max-width: 620px;
  position: relative;
  z-index: 4;
}

/* Eyebrow */
.sv-hero-eyebrow {
  color: rgba(255, 255, 255, 0.6);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 32px;
}

.sv-hero-eyebrow-dot {
  width: 6px;
  height: 6px;
  background: #ec1c24;
  border-radius: 50%;
  display: inline-block;
  box-shadow: 0 0 12px rgba(236, 28, 36, 0.6);
  animation: svHeroDotPulse 1.6s ease-in-out infinite;
  flex-shrink: 0;
}

@keyframes svHeroDotPulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

/* H1 heading */
.sv-hero-h1 {
  font-family: "Outfit", system-ui, sans-serif;
  color: #ffffff;
  font-size: clamp(40px, 5vw, 76px);
  font-weight: 600;
  letter-spacing: -0.035em;
  line-height: 1.02;
  margin-bottom: 28px;
  max-width: 14ch;
  text-wrap: balance;
}

.sv-hero-accent {
  color: #ec1c24;
}

/* Sub-paragraph */
.sv-hero-sub {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 18px;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.72);
  max-width: 540px;
  margin-bottom: 36px;
}

/* Button row */
.sv-hero-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 56px;
}

/* Button base — matches .btn from Claude Design styles.css */
.sv-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 172px;
  height: 56px;
  padding: 0 16px;
  border-radius: 5px;
  font-family: "Outfit", system-ui, sans-serif;
  font-weight: 500;
  font-size: 14px;
  letter-spacing: 0.01em;
  line-height: 1;
  transition: all 0.25s ease;
  cursor: pointer;
  border: 1.5px solid transparent;
  white-space: nowrap;
  text-decoration: none;
}

.sv-btn-primary {
  background: #ec1c24;
  color: #ffffff;
  border-color: #ec1c24;
}

.sv-btn-primary:hover {
  background: #ec1c24;
  transform: translateY(-2px);
  box-shadow:
    0 0 0 4px rgba(236, 28, 36, 0.18),
    0 16px 34px -10px rgba(236, 28, 36, 0.55);
  color: #ffffff;
  text-decoration: none;
}

.sv-btn-primary:hover,
.sv-btn-primary:focus,
.sv-btn-primary:active {
  border-color: #ec1c24;
  outline: none;
}

.sv-btn-primary:focus-visible {
  outline: none;
  box-shadow: 0 0 0 4px rgba(236, 28, 36, 0.35);
}

.sv-btn-ghost-light {
  background: transparent;
  color: #ffffff;
  border-color: #ffffff;
}

.sv-btn-ghost-light:hover {
  background: #ffffff;
  color: #0a0a0b;
  border-color: #ffffff;
  text-decoration: none;
}

/* ── RIGHT column: visual container ─────────────────────────────────────── */
.sv-hero-visual {
  position: relative;
  height: 560px;
  width: 100%;
  display: grid;
  place-items: center;
  pointer-events: none;
}

.sv-hero-visual.sv-anim-circle {
  pointer-events: auto;
  overflow: visible;
}

/* ══════════════════════════════════════════════════════════════════════════
   SvServiceCircleViz — exact port of Claude Design SvServiceCircleViz
   ══════════════════════════════════════════════════════════════════════════ */

/* Wrapper fills the .sv-hero-visual container */
.sv-svc {
  position: absolute;
  inset: 0;
  --svc-d: 520px;
  --svc-r: 290px;
}

/* Particle canvas fills background */
.sv-svc-particles {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}

/* Orbit wrapper — circle pushed to the right edge (partially off-viewport intentionally) */
.sv-svc-orbit {
  position: absolute;
  width: var(--svc-d);
  height: var(--svc-d);
  right: -190px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 1;
}

/* Central circular disc */
.sv-svc-disc {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  overflow: hidden;
  background: radial-gradient(
    70% 70% at 50% 45%,
    #14070a 0%,
    #0a0506 60%,
    #060304 100%
  );
  box-shadow:
    0 30px 80px -30px rgba(0, 0, 0, 0.85),
    inset 0 0 0 1px rgba(255, 255, 255, 0.08);
  animation: svcDiscIn 1s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

/* Plexus network canvas — fills the disc */
.sv-svc-plexus {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

/* Optional hero image inside the disc */
.sv-svc-disc img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transform: scale(1.05);
}

/* Dark tint + left red glow overlay on disc */
.sv-svc-disc-tint {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      120% 100% at 78% 50%,
      rgba(10, 10, 11, 0) 45%,
      rgba(10, 10, 11, 0.55) 100%
    ),
    radial-gradient(
      60% 55% at 30% 32%,
      rgba(236, 28, 36, 0.16),
      transparent 72%
    );
}

/* Spinning conic sheen over the disc */
.sv-svc-disc-sheen {
  position: absolute;
  inset: -25%;
  background: conic-gradient(
    from 0deg,
    transparent 0 70%,
    rgba(255, 255, 255, 0.08) 82%,
    transparent 92%
  );
  animation: svcSpin 18s linear infinite;
}

/* Prominent outer red glow (animated pulse) */
.sv-svc-orbit::before {
  content: "";
  position: absolute;
  inset: -16%;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgba(236, 28, 36, 0.55) 0%,
    rgba(236, 28, 36, 0.28) 42%,
    rgba(236, 28, 36, 0) 72%
  );
  filter: blur(26px);
  z-index: -1;
  pointer-events: none;
  animation: svcGlowPulse 5.5s ease-in-out infinite;
}

@keyframes svcGlowPulse {
  0%,
  100% {
    opacity: 0.7;
    transform: scale(1);
  }
  50% {
    opacity: 1;
    transform: scale(1.05);
  }
}

/* Rings */
.sv-svc-ring {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}
.sv-svc-ring.ring-solid {
  inset: -3px;
  border: 1px solid rgba(255, 255, 255, 0.16);
}
.sv-svc-ring.ring-dash {
  inset: -30px;
  border: 1px dashed rgba(236, 28, 36, 0.32);
  animation: svcSpin 70s linear infinite;
}

/* ── Radial chip positioning ─────────────────────────────────────────────
 * Each .sv-svc-chip-pos is centered at the orbit centre (top:50%;left:50%;w:0;h:0),
 * rotated by --chip-a, translated outward by --svc-r, then counter-rotated so the
 * chip stays upright. Mirrors React: `rotate(${s.a}deg) translateX(var(--svc-r)) rotate(${-s.a}deg)`
 */
.sv-svc-chip-pos {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  transform: rotate(var(--chip-a)) translateX(var(--svc-r))
    rotate(calc(-1 * var(--chip-a)));
}

/* Chip card — centred on the chip-pos anchor point */
.sv-svc-chip {
  position: absolute;
  top: 0;
  left: 0;
  transform: translate(-50%, -50%);
  animation: svcChipIn 0.6s ease both;
}

/* Per-chip fade-in stagger (chip-pos elements are children 4+ inside .sv-svc-orbit:
   child 1 = .sv-svc-disc, child 2 = .ring-solid, child 3 = .ring-dash) */
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(4) .sv-svc-chip {
  animation-delay: 0.2s;
}
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(5) .sv-svc-chip {
  animation-delay: 0.3s;
}
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(6) .sv-svc-chip {
  animation-delay: 0.4s;
}
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(7) .sv-svc-chip {
  animation-delay: 0.5s;
}
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(8) .sv-svc-chip {
  animation-delay: 0.6s;
}
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(9) .sv-svc-chip {
  animation-delay: 0.7s;
}
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(10) .sv-svc-chip {
  animation-delay: 0.8s;
}

/* Circular icon button */
.sv-svc-chip-ic {
  display: grid;
  place-items: center;
  width: 68px;
  height: 68px;
  border-radius: 50%;
  background: rgba(18, 22, 30, 0.78);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: #ffffff;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  box-shadow: 0 10px 26px -12px rgba(0, 0, 0, 0.8);
  animation: svcFloat 5s ease-in-out infinite;
  transition:
    transform 0.3s ease,
    border-color 0.3s ease,
    background 0.3s ease,
    box-shadow 0.3s ease;
  overflow: hidden;
}

.sv-svc-chip-ic svg {
  width: 30px;
  height: 30px;
  stroke-width: 1.7;
}
.sv-svc-chip-ic img {
  width: 30px;
  height: 30px;
  object-fit: contain;
}

/* Per-chip float stagger */
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(4) .sv-svc-chip-ic {
  animation-delay: 0s;
}
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(5) .sv-svc-chip-ic {
  animation-delay: 0.7s;
}
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(6) .sv-svc-chip-ic {
  animation-delay: 1.4s;
}
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(7) .sv-svc-chip-ic {
  animation-delay: 2.1s;
}
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(8) .sv-svc-chip-ic {
  animation-delay: 2.8s;
}
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(9) .sv-svc-chip-ic {
  animation-delay: 3.5s;
}
.sv-svc-orbit > .sv-svc-chip-pos:nth-child(10) .sv-svc-chip-ic {
  animation-delay: 4.2s;
}

/* Chip label — positioned to the LEFT of the icon (text points inward into viewport) */
.sv-svc-chip-label {
  position: absolute;
  right: calc(100% + 14px);
  top: 50%;
  transform: translateY(-50%);
  width: max-content;
  max-width: 168px;
  text-align: right;
  white-space: normal;
  line-height: 1.25;
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 13.5px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: rgba(255, 255, 255, 0.92);
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.85);
}

/* Hover effects */
.sv-svc-chip:hover .sv-svc-chip-ic {
  transform: scale(1.12);
  border-color: rgba(236, 28, 36, 0.7);
  background: rgba(236, 28, 36, 0.16);
  box-shadow: 0 14px 30px -10px rgba(236, 28, 36, 0.5);
}
