  margin-bottom: 20px;
}

/* Heading */
.sv-tools-h2 {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: clamp(32px, 4vw, 56px);
  font-weight: 600;
  letter-spacing: -0.025em;
  color: #0c2340;
