  margin: 0 auto 0;
}

.sv-tools-h2 span {
  color: #ec1c24;
}

/* Sub paragraph */
.sv-tools-sub {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 25px;
  line-height: 1.4;
  color: #4a4845;
  font-weight: 500;
  max-width: 900px;
  margin: auto;
  padding-top: 20px;
}

/* Tab row */
.sv-tabs {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-bottom: 40px;
  border-bottom: 1px solid #e8e5e0;
  padding-bottom: 18px;
}

.sv-tab {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 14px;
  font-weight: 500;
  color: #4a4845;
  padding: 10px 18px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: transparent;
  cursor: pointer;
  transition:
    color 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease;
}

.sv-tab:hover {
  color: #0c2340;
  border-color: #e8e5e0;
}

.sv-tab.is-active {
  color: #ffffff;
  background: #ec1c24;
  border-color: #ec1c24;
}

/* Tool grid */
.sv-tools-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

/* Tool card */
.sv-tool {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding: 28px 14px 22px;
  border: 1px solid #e8e5e0;
  border-radius: 16px;
  background: #ffffff;
  text-align: center;
  transition:
    transform 0.25s ease,
    border-color 0.25s ease,
    box-shadow 0.25s ease;
  animation: svToolFade 0.4s ease both;
}

.sv-tool:hover {
  transform: translateY(-4px);
  border-color: rgba(236, 28, 36, 0.22);
  box-shadow: 0 18px 40px -26px rgba(236, 28, 36, 0.4);
}

@keyframes svToolFade {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Color abbreviation tile */
.sv-tool-tile {
  width: 54px;
  height: 54px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  font-family: "Outfit", system-ui, sans-serif;
  font-weight: 700;
  font-size: 17px;
