}

.sv-tool-tile--logo img {
  width: 32px;
  height: 32px;
  object-fit: contain;
  display: block;
}

/* Tool name label */
.sv-tool-name {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 500;
  color: #0c2340;
  line-height: 1.3;
}

/* Panel visibility (controlled by JS) */
.sv-tools-panel[hidden] {
  display: none;
}

@media (max-width: 1024px) {
  .sv-tools-grid {
    grid-template-columns: repeat(4, 1fr);
