/* ── Hero ── */
.tc-hero {
  background: var(--tc-hero-bg);
  background-image:
    radial-gradient(
      ellipse 55% 50% at 78% 32%,
      var(--tc-accent-subtle) 0%,
      transparent 60%
    ),
