    ellipse 85% 75% at 60% 50%,
    #000 25%,
    transparent 82%
  );
}
.tc-hero-grid {
  max-width: var(--tc-container);
  margin: 0 auto;
  width: 100%;
  padding: 130px var(--tc-pad-x) 90px;
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(0, 1fr);
