  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 40px;
}

/* ── 3D Stack ── */
.tc-arch {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  max-width: 600px;
  margin-left: auto;
  justify-self: end;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  perspective: 1600px;
  overflow: visible;
}
.tc-hero-center-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  pointer-events: none;
}
.tc-stack3d {
  position: relative;
  width: 400px;
  margin-right: 10px;
  transform-style: preserve-3d;
  transform: rotateX(7deg) rotateY(-21deg) rotateZ(2deg);
  animation: tcStackFloat 7s ease-in-out infinite;
}
@keyframes tcStackFloat {
  0%,
  100% {
    transform: rotateX(7deg) rotateY(-21deg) rotateZ(2deg) translateY(0);
  }
  50% {
    transform: rotateX(7deg) rotateY(-21deg) rotateZ(2deg) translateY(-10px);
  }
}
.tc-stack-glow {
  position: absolute;
  left: -55%;
  right: -14%;
  top: 6%;
  bottom: 6%;
  background: radial-gradient(
    ellipse 58% 56% at 62% 50%,
    rgba(236, 28, 36, 0.2) 0%,
    transparent 70%
  );
  filter: blur(14px);
  transform: translateZ(-60px);
  pointer-events: none;
}
.tc-layer {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  height: 66px;
  margin-bottom: 16px;
  padding: 0 22px 0 24px;
  border-radius: 16px;
  background: linear-gradient(
    135deg,
    rgba(22, 32, 54, 0.82) 0%,
    rgba(10, 18, 32, 0.82) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow:
    0 22px 44px -26px rgba(0, 0, 0, 0.9),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
  transform: translateZ(calc(var(--i) * 26px));
  opacity: 0;
  animation: tcLayerIn 0.95s cubic-bezier(0.16, 0.84, 0.3, 1) forwards;
}
.tc-layer:last-child {
  margin-bottom: 0;
}
@keyframes tcLayerIn {
  0% {
    opacity: 0;
    transform: translateZ(calc(var(--i) * 26px)) translateX(-240px)
      translateY(var(--enterY));
  }
  60% {
    opacity: 1;
  }
  100% {
    opacity: 1;
    transform: translateZ(calc(var(--i) * 26px)) translateX(0) translateY(0);
  }
}
.tc-layer-guide {
  position: absolute;
  right: calc(100% - 8px);
  top: 50%;
  width: 230px;
  height: 1px;
  margin-top: -0.5px;
  background: linear-gradient(
    270deg,
    rgba(236, 28, 36, 0.45) 0%,
    rgba(236, 28, 36, 0.12) 38%,
    transparent 100%
  );
  pointer-events: none;
  overflow: visible;
}
.tc-layer-bead {
  position: absolute;
  top: 50%;
  left: 0;
  width: 5px;
  height: 5px;
  margin-top: -2.5px;
  border-radius: 50%;
  background: #ec1c24;
  box-shadow: 0 0 8px rgba(236, 28, 36, 0.9);
  opacity: 0;
  animation: tcBead 3.6s ease-in-out infinite;
}
@keyframes tcBead {
  0% {
    left: 0;
    opacity: 0;
  }
  12% {
    opacity: 1;
  }
  70% {
    left: 224px;
    opacity: 1;
  }
  85% {
    left: 224px;
    opacity: 0;
  }
  100% {
    left: 224px;
    opacity: 0;
  }
}
.tc-layer-bar {
  position: absolute;
  left: 0;
  top: 12px;
  bottom: 12px;
  width: 3px;
  border-radius: 3px;
  background: #ec1c24;
  box-shadow: 0 0 12px rgba(236, 28, 36, 0.7);
}
.tc-layer-idx {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 12px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.35);
  letter-spacing: 0.04em;
}
.tc-layer-ic {
  width: 34px;
