  align-items: center;
  justify-content: center;
  font-family: "Outfit", system-ui, sans-serif;
  font-weight: 700;
  font-size: 16px;
  letter-spacing: -0.02em;
  background: var(--tile-tint, rgba(12, 35, 64, 0.05));
  color: var(--tile-fg, #0c2340);
  border: 1px solid var(--tile-line, rgba(12, 35, 64, 0.1));
  transition: transform 0.25s ease;
  overflow: hidden;
}
.tc-tile img {
  width: 32px;
  height: 32px;
  object-fit: contain;
}

/* ── Desktop: rail + panel layout ── */
.tc-stack-layout {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 40px;
  margin-top: 56px;
  align-items: start;
}
.tc-panels-wrap {
  min-width: 0;
}
.tc-panel[hidden] {
  display: none;
}
.tc-panel {
  border: 1px solid #e5e5e5;
  border-radius: 24px;
  background: #ffffff;
  padding: 36px 36px 40px;
  min-height: 520px;
  position: relative;
  overflow: hidden;
}

/* Category rail */
.tc-cat-rail {
  display: flex;
  flex-direction: column;
  gap: 8px;
  position: sticky;
  top: 96px;
}
.tc-cat-btn {
  display: flex;
  align-items: center;
  gap: 16px;
  width: 100%;
  text-align: left;
  padding: 18px 20px;
  border-radius: 16px;
  border: 1px solid #e5e5e5;
  background: #ffffff;
  cursor: pointer;
  transition: all 0.25s ease;
  position: relative;
}
.tc-cat-btn:hover {
  border-color: rgba(236, 28, 36, 0.3);
  transform: translateX(2px);
}
.tc-cat-btn.is-active {
  border-color: transparent;
  background: #0c2340;
  box-shadow: 0 18px 40px -22px rgba(12, 35, 64, 0.5);
}
.tc-cat-btn-icon {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  border-radius: 12px;
  background: rgba(236, 28, 36, 0.08);
  color: #ec1c24;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.25s ease;
  overflow: hidden;
}
.tc-cat-btn-icon img {
  width: 24px;
  height: 24px;
  object-fit: contain;
}
.tc-cat-btn-icon svg {
  width: 22px;
  height: 22px;
}
.tc-cat-btn.is-active .tc-cat-btn-icon {
  background: #ec1c24;
  color: #ffffff;
}
.tc-cat-btn-text {
  min-width: 0;
  flex: 1;
}
.tc-cat-btn-title {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 16px;
  font-weight: 600;
  color: #0c2340;
  letter-spacing: -0.01em;
  transition: color 0.25s ease;
  display: block;
}
.tc-cat-btn.is-active .tc-cat-btn-title {
  color: #ffffff;
}
.tc-cat-btn-chev {
  display: flex;
  align-items: center;
  color: #8a8f99;
  opacity: 0;
  transform: translateX(-4px);
  transition: all 0.25s ease;
  flex-shrink: 0;
}
.tc-cat-btn.is-active .tc-cat-btn-chev {
  color: #ec1c24;
  opacity: 1;
  transform: translateX(0);
}

/* Right panel */
.tc-panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
}
.tc-panel-title {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: clamp(24px, 2.2vw, 30px);
  font-weight: 600;
  color: #0c2340;
  letter-spacing: -0.02em;
  margin: 0 0 8px;
}
.tc-panel-desc {
  font-size: 15.5px;
  line-height: 1.55;
  color: #555555;
  margin: 0;
  max-width: 560px;
}

/* Tech card grid */
.tc-tech-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 14px;
}
.tc-tech-card {
  display: flex;
  gap: 16px;
  padding: 20px;
  border-radius: 16px;
  background: #ffffff;
  border: 1px solid #e5e5e5;
  text-decoration: none;
  color: inherit;
  transition:
    transform 0.25s ease,
    border-color 0.25s ease,
    box-shadow 0.25s ease;
  animation: tstFadeUp 0.5s cubic-bezier(0.18, 0.9, 0.3, 1.05) backwards;
}
.tc-tech-card:hover {
  transform: translateY(-3px);
  border-color: rgba(236, 28, 36, 0.28);
  box-shadow: 0 16px 36px -22px rgba(236, 28, 36, 0.3);
}
.tc-tech-card:hover .tc-tile {
  transform: scale(1.05);
}
.tc-tech-card-body {
  min-width: 0;
  flex: 1;
}
.tc-tech-name {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 17px;
  font-weight: 600;
  color: #0c2340;
  margin: 0 0 5px;
  letter-spacing: -0.01em;
}
.tc-tech-desc {
  font-size: 13.5px;
  line-height: 1.5;
  color: #555555;
  margin: 0;
}
.tc-tech-arrow-circle {
  flex-shrink: 0;
  align-self: center;
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  border: 1.5px solid #ec1c24;
  color: #ec1c24;
  background: transparent;
  transition:
    background 0.25s ease,
    color 0.25s ease,
    transform 0.25s ease;
}
.tc-tech-arrow-circle svg {
  width: 15px;
  height: 15px;
}
.tc-tech-card:hover .tc-tech-arrow-circle {
  background: #ec1c24;
  color: #ffffff;
  transform: translateX(2px);
}
@keyframes tstFadeUp {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ── Mobile accordion ── */
.tc-acc {
  display: none;
  margin-top: 40px;
}
.tc-acc-item {
  border: 1px solid #e5e5e5;
  border-radius: 18px;
  background: #ffffff;
  margin-bottom: 12px;
  overflow: hidden;
}
.tc-acc-item.is-open {
  border-color: rgba(236, 28, 36, 0.25);
}
.tc-acc-q {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px;
  background: transparent;
  border: none;
  cursor: pointer;
  text-align: left;
}
.tc-acc-q .tc-cat-btn-icon {
  width: 40px;
  height: 40px;
}
.tc-acc-q-text {
  flex: 1;
}
.tc-acc-q-title {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 16px;
  font-weight: 600;
  color: #0c2340;
}
.tc-acc-plus {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(236, 28, 36, 0.08);
  color: #ec1c24;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: all 0.3s ease;
}
.tc-acc-item.is-open .tc-acc-plus {
  background: #ec1c24;
  color: #ffffff;
  transform: rotate(45deg);
}
.tc-acc-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}
.tc-acc-item.is-open .tc-acc-body {
  max-height: 2200px;
}
.tc-acc-body-inner {
  padding: 0 20px 20px;
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

/* ── Responsive ── */
@media (max-width: 1100px) {
  .tc-stack {
    padding: clamp(56px, 8vw, 90px) 32px;
  }
}
@media (max-width: 980px) {
  .tc-stack-layout {
    display: none;
  }
  .tc-acc {
    display: block;
  }
}
@media (max-width: 900px) {
  .tc-stack {
    padding: 56px 24px;
  }
  .tc-head-center {
    margin-bottom: 40px;
  }
}
@media (max-width: 640px) {
  .tc-tech-grid {
    grid-template-columns: 1fr;
  }
  .tc-panel {
    padding: 24px 20px 28px;
  }
}

/* ============================================================
   AI HUB — tc-ai (Technology-aihub.php)
   ============================================================ */

/* ── Section ── */
.tc-ai {
  background: #ffffff;
  position: relative;
  overflow: hidden;
  padding: 80px 0;
}
.tai-head-cta {
  margin-top: 28px;
}

/* ── Layout wrapper ── */
.tc-ai-layout {
  display: block;
  max-width: 1100px;
  margin: 0 auto;
}

/* ── Tab button bar ── */
.tc-ai-btnbar {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-bottom: 28px;
}
.tc-ai-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 16px;
  border-radius: 999px;
  border: 1px solid #e5e5e5;
  background: #ffffff;
  color: #0c2340;
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.25s ease;
}
.tc-ai-btn:hover {
  border-color: rgba(236, 28, 36, 0.4);
  transform: translateY(-1px);
}
.tc-ai-btn.is-active {
  background: #ec1c24;
  border-color: #ec1c24;
  color: #ffffff;
  box-shadow: 0 14px 32px -18px rgba(236, 28, 36, 0.6);
}

/* ── Detail panel ── */
.tc-ai-detail {
  background: #ffffff;
  border: 1px solid #e5e5e5;
  border-radius: 24px;
  padding: 34px 34px 36px;
  box-shadow: 0 30px 70px -40px rgba(12, 35, 64, 0.3);
}
.tc-ai-detail[hidden] {
  display: none;
}
.tc-ai-detail-title {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 26px;
  font-weight: 600;
  color: #0c2340;
  margin: 0 0 10px;
  letter-spacing: -0.02em;
}
.tc-ai-detail-desc {
  font-size: 15px;
  line-height: 1.6;
  color: #555555;
  margin: 0 0 24px;
}

/* ── Tech list (2-col grid) ── */
.tc-ai-techlist {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
.tc-ai-techrow {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border-radius: 13px;
  background: #ffffff;
  border: 1px solid #e5e5e5;
  transition: border-color 0.2s ease;
  animation: tcFadeUp 0.4s ease backwards;
}
.tc-ai-techrow:hover {
  border-color: rgba(236, 28, 36, 0.25);
}
.tc-ai-techrow-body {
  min-width: 0;
}
.tc-ai-techrow-name {
  font-size: 15.5px;
  font-weight: 600;
  color: #0c2340;
}
.tc-ai-techrow-role {
  font-size: 13px;
  color: #555555;
  margin-top: 2px;
  line-height: 1.4;
}

/* ── Tile small variant ── */
.tc-tile.is-sm {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  font-size: 13px;
}
.tc-tile.is-sm img {
  width: 28px;
  height: 28px;
  object-fit: contain;
}

/* ── Shared tcFadeUp keyframe ── */
@keyframes tcFadeUp {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ── Bottom note ── */
.tc-ai-note {
  margin: 40px auto 0;
  max-width: 760px;
  padding: 20px 28px;
  background: #ffffff;
  border: 1px solid #e5e5e5;
  border-radius: 16px;
  box-shadow: 0 18px 44px -30px rgba(12, 35, 64, 0.3);
  font-size: 15.5px;
  line-height: 1.55;
  color: #0c2340;
  font-weight: 500;
  display: flex;
  gap: 14px;
  align-items: center;
  text-align: center;
}
.tc-ai-note span {
  flex: 1;
}
.tc-ai-note::before {
  content: "";
  width: 8px;
  height: 8px;
  flex-shrink: 0;
  border-radius: 50%;
  background: #ec1c24;
  box-shadow: 0 0 0 4px rgba(236, 28, 36, 0.08);
}

/* ── Responsive ── */
@media (max-width: 900px) {
  .tc-ai {
    padding: 56px 24px;
  }
  .tc-ai-detail {
    padding: 24px 20px 28px;
  }
}
@media (max-width: 640px) {
  .tc-ai-techlist {
    grid-template-columns: 1fr;
  }
  .tc-ai-btnbar {
    flex-wrap: wrap;
  }
  .tc-ai-btn {
    font-size: 12px;
    padding: 8px 12px;
  }
}

/* ============================================================
   LOCATION BANNER / HERO — loc-hero (Location-banner.php)
   ============================================================ */

/* ── CSS variables (scoped to section) ── */
.loc-hero {
  --loc-red: #ec1c24;
  --loc-navy: #0c2340;
  --loc-muted: #555555;
  --loc-line: #e5e5e5;
  --loc-pad-y: 90px;
  --loc-pad-x: 48px;
  --loc-container: 1320px;
}

/* ── Base section ── */
.loc-hero {
  padding: 140px var(--loc-pad-x) var(--loc-pad-y);
  background: #ffffff;
  position: relative;
  overflow: hidden;
  min-height: 680px;
}
.loc-hero::before {
  content: "";
  position: absolute;
  right: -120px;
  top: -80px;
  width: 700px;
  height: 700px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgba(236, 28, 36, 0.06) 0%,
    transparent 65%
  );
  pointer-events: none;
}

/* ── Light + onblack variant (the rendered combo) ── */
.loc-hero.loc-hero-light {
  min-height: 760px;
  display: flex;
  align-items: center;
}
.loc-hero.loc-hero-light .loc-hero-grid {
  width: 100%;
  grid-template-columns: 1.02fr 0.98fr;
  gap: 56px;
  align-items: center;
}

.loc-hero.loc-hero-onblack {
  background: #0a0a0a;
  background-image:
    radial-gradient(
      900px 600px at 80% 38%,
      rgba(236, 28, 36, 0.13) 0%,
      transparent 60%
    ),
    radial-gradient(
      720px 520px at 12% 88%,
      rgba(40, 80, 180, 0.1) 0%,
      transparent 62%
    );
  overflow: hidden;
}
.loc-hero.loc-hero-onblack::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(
    rgba(255, 255, 255, 0.05) 1px,
    transparent 1px
  );
  background-size: 28px 28px;
  opacity: 0.32;
  pointer-events: none;
  -webkit-mask-image: radial-gradient(
    ellipse 80% 70% at 50% 50%,
    #000 30%,
    transparent 80%
  );
  mask-image: radial-gradient(
    ellipse 80% 70% at 50% 50%,
    #000 30%,
    transparent 80%
  );
}
.loc-hero.loc-hero-onblack .loc-hero-grid {
  position: relative;
  z-index: 2;
}
.loc-hero.loc-hero-onblack .loc-hero-h1 {
  color: #ffffff;
}
.loc-hero.loc-hero-onblack .loc-hero-sub {
  color: rgba(255, 255, 255, 0.66);
}
.loc-hero.loc-hero-onblack .loc-btn-secondary {
  color: #ffffff;
  border-color: #ffffff;
}
.loc-hero.loc-hero-onblack .loc-btn-secondary:hover {
  background: #ffffff;
  color: #000000;
  border-color: #ffffff;
}

/* ── Grid ── */
.loc-hero-grid {
  max-width: var(--loc-container);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 40px;
  align-items: center;
}

/* ── Left content ── */
.loc-hero-content {
  max-width: 580px;
  position: relative;
  z-index: 3;
}
.loc-hero.loc-hero-light .loc-hero-content {
  max-width: 560px;
}

/* ── Heading ── */
.loc-hero-h1 {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: clamp(44px, 5.2vw, 75px);
  font-weight: 700;
  color: var(--loc-navy);
  letter-spacing: -0.035em;
  line-height: 1.04;
  margin: 0 0 24px;
}
.lhb-accent {
  color: #ec1c24;
}

/* ── Sub-text ── */
.loc-hero-sub {
  font-size: clamp(18px, 1.5vw, 22px);
  font-weight: 500;
  line-height: 1.55;
  color: var(--loc-muted);
  margin: 0 0 36px;
  max-width: 540px;
}

/* ── CTA row ── */
.loc-hero-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

/* ── Buttons ── */
.loc-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 0 28px;
  height: 56px;
  background: #ec1c24;
  color: #ffffff;
  border: none;
  border-radius: 8px;
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 15px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.25s ease;
  white-space: nowrap;
}
.loc-btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 32px -8px rgba(236, 28, 36, 0.45);
  color: #ffffff;
}
.loc-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 0 28px;
  height: 56px;
  background: transparent;
  color: var(--loc-navy);
  border: 1.5px solid var(--loc-line);
  border-radius: 8px;
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 15px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.25s ease;
  white-space: nowrap;
}
.loc-btn-secondary:hover {
  border-color: #ec1c24;
  color: #ec1c24;
  transform: translateY(-1px);
}

/* ── Right column: visual (image + items) ── */
.lhb-visual {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 20px;
  width: 100%;
  max-width: 580px;
  flex-shrink: 0;
}

/* ── Hero image ── */
.lhb-globe-img {
  width: 100%;
  border-radius: 20px;
  overflow: hidden;
}
.lhb-globe-img img {
  width: 100%;
  height: auto;
  display: block;
  object-fit: cover;
  border-radius: 20px;
}

/* ── Items grid ── */
.lhb-items {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.lhb-item {
  display: flex;
  gap: 12px;
  padding: 16px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 14px;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition:
    border-color 0.25s ease,
    background 0.25s ease;
}
.lhb-item:hover {
  background: rgba(255, 255, 255, 0.09);
  border-color: rgba(236, 28, 36, 0.35);
}
.lhb-item-ic {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: 10px;
  background: rgba(236, 28, 36, 0.15);
  border: 1px solid rgba(236, 28, 36, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ff8a8f;
  overflow: hidden;
}
.lhb-item-ic img {
  width: 28px;
  height: 28px;
  object-fit: contain;
}
.lhb-item-ic svg {
  width: 18px;
  height: 18px;
}
.lhb-item-body {
  min-width: 0;
}
.lhb-item-title {
  display: block;
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 14px;
  font-weight: 600;
  color: #ffffff;
  letter-spacing: -0.01em;
  margin-bottom: 4px;
}
.lhb-item-desc {
  font-size: 12.5px;
  line-height: 1.5;
  color: rgba(255, 255, 255, 0.58);
  margin: 0;
}

/* ── Responsive ── */
@media (max-width: 1600px) {
  .loc-hero {
    padding-top: 50px;
    padding-bottom: 30px;
    min-height: 620px;
  }
  .loc-hero.loc-hero-light {
    min-height: 640px;
  }
}
@media (max-width: 1440px) {
  .loc-hero {
    padding-top: 0px;
    padding-bottom: 00px;
    min-height: 80vh;
  }
  .loc-hero.loc-hero-light {
    min-height: 80vh;
  }
}

/* ── Responsive ── */
@media (max-width: 1100px) {
  .loc-hero {
    padding-top: 100px;
    min-height: auto;
  }
  .loc-hero.loc-hero-light {
    min-height: auto;
  }
  .loc-hero-grid,
  .loc-hero.loc-hero-light .loc-hero-grid {
    grid-template-columns: 1fr;
    gap: 48px;
  }
  .lhb-visual {
    max-width: 560px;
    margin: 0 auto;
  }
}
@media (max-width: 768px) {
  .lhb-items {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 640px) {
  .loc-hero {
    padding: 90px 24px 60px;
  }
  .loc-hero.loc-hero-light {
    min-height: auto;
  }
  .loc-hero-actions {
    flex-direction: column;
  }
  .loc-btn-primary,
  .loc-btn-secondary {
    width: 100%;
  }
  .lhb-visual {
    max-width: 100%;
  }
}

/* ============================================================
   Location Hero — Canvas Globe
   ============================================================ */

/* ── Globe container ──────────────────────────────────────── */
.loc-hero-globe {
  position: relative;
  width: 100%;
  height: 560px;
  max-width: 660px;
  margin-left: auto;
  flex-shrink: 0;
}

@media (max-width: 1600px) {
  .loc-hero-globe {
    height: 480px;
    max-width: 580px;
  }
}
@media (max-width: 1440px) {
  .loc-hero-globe {
    height: 420px;
    max-width: 520px;
  }
}

.lhb-globe-canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* ── Dot-grid overlay (decorative) ───────────────────────── */
.loc-hero-globe::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.07) 1px,
    transparent 1px
  );
  background-size: 32px 32px;
  pointer-events: none;
  z-index: 0;
}

.loc-hero-globe canvas {
  position: relative;
  z-index: 1;
}

/* ── Radial glow behind globe ─────────────────────────────── */
.loc-hero-globe::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    ellipse 60% 60% at 50% 50%,
    rgba(236, 28, 36, 0.06) 0%,
    transparent 70%
  );
  pointer-events: none;
  z-index: 0;
}

/* ── Responsive ───────────────────────────────────────────── */
@media (max-width: 1100px) {
  .loc-hero-globe {
    height: 420px;
    max-width: 560px;
    margin: 0 auto;
  }
}

@media (max-width: 768px) {
  .loc-hero-globe {
    height: 340px;
    max-width: 100%;
  }
}

@media (max-width: 480px) {
  .loc-hero-globe {
    height: 280px;
  }
}

/* ── Location Hero — image override wrapper ──────────────────────────────── */
.lhb-hero-img-wrap {
  width: 100%;
  max-width: 660px;
  margin-left: auto;
  display: flex;
  align-items: center;
  justify-content: center;
}

.lhb-hero-img-wrap img {
  width: 100%;
  height: auto;
  display: block;
  border-radius: 12px;
  object-fit: contain;
}

@media (max-width: 1100px) {
  .lhb-hero-img-wrap {
    max-width: 560px;
    margin: 0 auto;
  }
}

@media (max-width: 768px) {
  .lhb-hero-img-wrap {
    max-width: 100%;
  }
}

/* ── Location Hero Globe — exact match to Claude Design (overrides previous) ── */
.loc-hero-globe {
  position: relative;
  width: 660px;
  height: 560px;
  flex-shrink: 0;
}

.loc-hero-globe canvas,
.lhb-globe-canvas {
  display: block;
  width: 660px;
  height: 560px;
  position: static;
  z-index: auto;
}

/* Remove decorative overlays — not in Claude Design */
.loc-hero-globe::before,
.loc-hero-globe::after {
  display: none;
}

@media (max-width: 1100px) {
  .loc-hero-globe {
    width: 100%;
    height: auto;
    aspect-ratio: 660 / 560;
    margin: 0 auto;
    max-width: 560px;
  }
  .loc-hero-globe canvas,
  .lhb-globe-canvas {
    width: 100% !important;
    height: auto !important;
