/* ============================================================
   LOCATION CARDS — 3D Carousel  (Location-cards.php)
   ============================================================ */

.loc-markets {
  --loc-red: #ec1c24;
  --loc-navy: #0c2340;
  --loc-muted: #555555;
  --loc-line: #e5e5e5;
  --loc-container: 1320px;
  background: #ffffff;
  padding: 90px 48px;
  position: relative;
  font-family: "Outfit", system-ui, sans-serif;
}

.loc-markets-inner {
  max-width: var(--loc-container);
  margin: 0 auto;
}

/* ── Head ── */
.loc-markets-head {
  text-align: center;
  max-width: 1000px;
  margin: 0 auto 64px;
}

.loc-markets-subtitle {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--loc-red);
  margin: 0 0 14px;
}

.loc-markets-h2 {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: clamp(32px, 4.2vw, 56px);
  font-weight: 600;
  color: var(--loc-navy);
  letter-spacing: -0.025em;
  line-height: 1.08;
  margin: 0;
}

.loc-markets-sub {
  font-size: clamp(16px, 1.4vw, 19px);
  line-height: 1.65;
  color: var(--loc-muted);
  margin: 20px auto 0;
  max-width: 720px;
}

/* ── 3D Carousel ── */
.loc-carousel {
  position: relative;
  max-width: 1100px;
  margin: 0 auto;
  height: 520px;
  perspective: 1800px;
  transform-style: preserve-3d;
}

.loc-card {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 400px;
  height: 450px;
  margin-left: -190px;
  margin-top: -220px;
  background: #ffffff;
  border: 1px solid var(--loc-line);
  border-radius: 24px;
  overflow: hidden;
  cursor: pointer;
  transition: all 0.6s cubic-bezier(0.18, 0.9, 0.3, 1.05);
  box-shadow: 0 20px 50px -25px rgba(12, 35, 64, 0.18);
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: inherit;
}

.loc-card.is-active {
  transform: translate3d(0, 0, 0) scale(1);
  opacity: 1;
  z-index: 10;
  box-shadow: 0 32px 64px -20px rgba(12, 35, 64, 0.28);
  border-color: rgba(236, 28, 36, 0.2);
}

.loc-card.is-left {
  transform: translate3d(-320px, 20px, -200px) scale(0.82) rotateY(12deg);
  opacity: 0.85;
  z-index: 5;
}

.loc-card.is-right {
  transform: translate3d(320px, 20px, -200px) scale(0.82) rotateY(-12deg);
  opacity: 0.85;
  z-index: 5;
}

.loc-card.is-far-left {
  transform: translate3d(-540px, 40px, -400px) scale(0.65) rotateY(18deg);
  opacity: 0.5;
  z-index: 2;
}

.loc-card.is-far-right {
  transform: translate3d(540px, 40px, -400px) scale(0.65) rotateY(-18deg);
  opacity: 0.5;
  z-index: 2;
}

.loc-card:hover.is-active {
  transform: translate3d(0, -6px, 0);
  box-shadow: 0 36px 72px -18px rgba(12, 35, 64, 0.32);
}

.loc-card:hover.is-left {
  transform: translate3d(-310px, 14px, -180px) scale(0.84) rotateY(10deg);
}
.loc-card:hover.is-right {
  transform: translate3d(310px, 14px, -180px) scale(0.84) rotateY(-10deg);
}

/* ── Card inner ── */
.loc-card-img {
  width: 100%;
  height: 200px;
  object-fit: cover;
  display: block;
  flex-shrink: 0;
}

.loc-card-body {
  flex: 1;
  padding: 24px 28px 28px;
  display: flex;
  flex-direction: column;
}

.loc-card-city {
  font-family: "Outfit", system-ui, sans-serif;
  font-size: 24px;
  font-weight: 600;
  color: var(--loc-navy);
  margin: 0 0 10px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.loc-card-city-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--loc-red);
  flex-shrink: 0;
}

.loc-card-desc {
  font-size: 15px;
  line-height: 1.6;
  color: var(--loc-muted);
  margin: 0;
  flex: 1;
}

.loc-card-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  color: var(--loc-red);
  margin-top: 16px;
  text-decoration: none;
  transition: gap 0.25s ease;
}

.loc-card:hover .loc-card-link {
  gap: 12px;
}

/* ── Carousel navigation ── */
.loc-carousel-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 36px;
}

.loc-carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 1px solid var(--loc-line);
  background: #ffffff;
  color: var(--loc-navy);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s ease;
  padding: 0;
  font-size: 0;
  line-height: 0;
}

.loc-carousel-btn:hover {
  background: var(--loc-red);
  color: #ffffff;
  border-color: var(--loc-red);
}

.loc-carousel-dots {
  display: flex;
  gap: 8px;
  align-items: center;
}

.loc-carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--loc-line);
  border: none;
  cursor: pointer;
  transition: all 0.25s ease;
  padding: 0;
}

.loc-carousel-dot.is-active {
  background: var(--loc-red);
  width: 24px;
  border-radius: 4px;
}

/* ── CTA ── */
.loc-markets-cta {
  text-align: center;
  margin-top: 56px;
}

/* ── Responsive ── */
@media (max-width: 900px) {
  .loc-carousel {
    height: auto;
    perspective: none;
  }

  .loc-card {
    position: relative;
    left: auto;
    top: auto;
    margin: 0 auto 20px;
    width: 100%;
    max-width: 380px;
    height: auto;
    transform: none !important;
    opacity: 1 !important;
  }

  .loc-card:not(.is-active) {
    display: none;
  }
  .loc-card.is-active {
    display: flex;
  }
}

@media (max-width: 768px) {
  .loc-markets {
    padding: 60px 24px;
  }
  .loc-markets-head {
    margin-bottom: 48px;
  }
}

@media (max-width: 640px) {
  .loc-markets {
    padding: 48px 16px;
  }
  .loc-markets-head {
    max-width: 100%;
  }
}

