.sa-ps-badge-ok { background: #b7e948; color: #1a1a1a; }
.sa-ps-card { position: relative; background: #ececed; border-radius: 22px; padding: 36px 32px; display: flex; flex-direction: column; gap: 14px; }
.sa-ps-card-problem { min-height: 300px; justify-content: center; background: #fff; border: 1px solid var(--sa-line); }
.sa-ps-card-solution { min-height: 300px; justify-content: center; background: #fff; border: 1px solid var(--sa-line); }
.sa-ps-card h3 { margin: 0; font-size: 32px; font-weight: 600; color: var(--sa-ink); letter-spacing: -0.01em; line-height: 1.15; }
