.sa-ps-node { position: absolute; width: 12px; height: 12px; border-radius: 50%; background: #fff; border: 2px solid var(--sa-ink); top: 50%; transform: translateY(-50%); z-index: 3; }
.sa-ps-node-out { right: -6px; }
.sa-ps-node-in { left: -6px; }
