.sa-ps-arrow { stroke: var(--sa-ink); stroke-width: 1.5; fill: none; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 1 7; opacity: 0; animation: saArrowFade 0.8s ease 0.3s forwards; }
.sa-ps-nav { display: flex; align-items: center; justify-content: center; gap: 20px; margin-top: 8px; }
.sa-ps-nav-prev, .sa-ps-nav-next { all: unset; width: 40px; height: 40px; border-radius: 10px; display: flex; align-items: center; justify-content: center; cursor: pointer; font-size: 18px; background: rgba(12,35,64,0.08); color: var(--sa-ink); transition: all 0.3s ease; }
.sa-ps-nav-prev:hover:not(:disabled), .sa-ps-nav-next:hover:not(:disabled) { background: var(--sa-red); color: #fff; }
.sa-ps-nav-prev:disabled, .sa-ps-nav-next:disabled { opacity: 0.3; cursor: not-allowed; }
.sa-ps-dots { display: flex; gap: 10px; }
