/* ---------- HERO VISUAL — live team assembly (.dt-hire) ---------- */
/* These two live with the abandoned .dt-plex variant in the approved sheet, but
   .dt-hire-core and its halo are the only remaining consumers, so they travel
   with the orbit rather than with the variant that was dropped. */
@keyframes dtCoreBob { 0%,100% { transform: translate(-50%,-50%) translateY(0); } 50% { transform: translate(-50%,-50%) translateY(-4%); } }
@keyframes dtHalo { 0%,100% { transform: scale(1); opacity: .8; } 50% { transform: scale(1.06); opacity: 1; } }
.dt-hire { position: relative; z-index: 2; width: 100%; max-width: 500px; margin: 0 auto; aspect-ratio: 1; }
.dt-hire-spokes { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; z-index: 1; }
.dt-hire-spoke { fill: none; stroke: rgba(236,28,36,0.55); stroke-width: 2; stroke-linecap: round; vector-effect: non-scaling-stroke; stroke-dasharray: 60; stroke-dashoffset: 60; animation: dtSpokeDraw .6s ease forwards; }
.dt-hire-slot { position: absolute; aspect-ratio: 1; transform: translate(-50%,-50%); z-index: 2; }
.dt-hire-empty { display: grid; place-items: center; width: 100%; height: 100%; border-radius: 50%; color: rgba(255,255,255,0.28); border: 2px dashed rgba(255,255,255,0.22); background: rgba(255,255,255,0.03); }
.dt-hire-empty svg { width: 34%; height: 34%; }
.dt-hire-node { position: relative; display: block; width: 100%; height: 100%; border-radius: 50%; animation: dtHirePop .5s cubic-bezier(.34,1.56,.64,1); }
.dt-hire-node img { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; display: block; border: 4px solid #fff; background: #0d121b; box-shadow: 0 18px 40px -18px rgba(0,0,0,0.85); }
.dt-hire-node.fresh img { border-color: #37C96B; box-shadow: 0 0 0 4px rgba(55,201,107,0.28), 0 18px 40px -18px rgba(0,0,0,0.85); animation: dtHireGlow 1s ease; }
.dt-hire-badge { position: absolute; top: -12%; left: 50%; transform: translateX(-50%); display: inline-flex; align-items: center; gap: 3px; white-space: nowrap; font-size: 10px; font-weight: 700; color: #fff; background: #37C96B; padding: 3px 8px; border-radius: 100px; box-shadow: 0 6px 14px -4px rgba(55,201,107,0.6); animation: dtBadgePop .45s cubic-bezier(.34,1.56,.64,1); }
.dt-hire-badge svg { width: 11px; height: 11px; }
.dt-hire-role { position: absolute; left: 50%; top: 100%; margin-top: 8px; transform: translateX(-50%) translateY(4px); white-space: nowrap; font-family: 'Outfit', system-ui, sans-serif; font-size: 11.5px; font-weight: 600; letter-spacing: 0.01em; color: #fff; background: rgba(12,35,64,0.82); border: 1px solid rgba(255,255,255,0.16); padding: 3px 9px; border-radius: 999px; backdrop-filter: blur(4px); opacity: 0; pointer-events: none; transition: opacity .4s ease, transform .4s cubic-bezier(.34,1.56,.64,1); z-index: 4; }
.dt-hire-role.on { opacity: 1; transform: translateX(-50%) translateY(0); }
.dt-hire-core { position: absolute; left: 50%; top: 50%; transform: translate(-50%,-50%); aspect-ratio: 1; z-index: 3; display: grid; place-items: center; animation: dtCoreBob 6s ease-in-out infinite; }
.dt-hire-prog { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); }
.dt-hire-track { fill: none; stroke: rgba(255,255,255,0.14); stroke-width: 2; }
.dt-hire-fill { fill: none; stroke: #EC1C24; stroke-width: 2.4; stroke-linecap: round; transition: stroke-dashoffset .7s cubic-bezier(.22,1,.36,1); filter: drop-shadow(0 0 4px rgba(236,28,36,0.6)); }
.dt-hire-core-inner { width: 74%; height: 74%; border-radius: 50%; display: grid; place-items: center; background: linear-gradient(155deg, #23262E, #0A0C11); border: 1px solid rgba(255,255,255,0.12); box-shadow: inset 0 1px 0 rgba(255,255,255,0.08), 0 20px 46px -20px rgba(0,0,0,0.85); }
.dt-hire-core-inner svg { width: 50%; height: 50%; }
