/* ---------- BUTTONS ---------- */
.dt-btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; height: 54px; padding: 0 28px; border-radius: 8px; font-family: inherit; font-size: 16px; font-weight: 600; border: 1.5px solid transparent; cursor: pointer; text-decoration: none; transition: transform .25s ease, box-shadow .25s ease, background .25s ease, color .25s ease, border-color .25s ease; white-space: nowrap; }
