/* A fixed ratio, so uploads of different sizes cannot make the row ragged. */
.so-hire-img { aspect-ratio: 4 / 3; overflow: hidden; }
.so-hire-img img { width: 100%; height: 100%; object-fit: cover; display: block; }
.so-hire-body { padding: 20px 22px 24px; display: flex; flex-direction: column; gap: 7px; }
.so-hire-body b { font-family: 'Outfit', system-ui, sans-serif; font-size: 17px; font-weight: 600; letter-spacing: -0.01em; color: var(--dt-ink); }
.so-hire-rd { display: block; font-size: 14.5px; line-height: 1.5; color: var(--dt-muted); }

@media (prefers-reduced-motion: reduce) {
