 .sa-ps-stage { grid-template-columns: 1fr; gap: 20px; } .sa-ps-col-right { margin-top: 0; } .sa-ps-connector { display: none; } .sa-ps-title { font-size: 30px; } .sa-ps-card-problem, .sa-ps-card-solution { min-height: 0; padding: 32px 28px; } 
  .dt-ps-stage { grid-template-columns: 1fr; gap: 20px; }
  .dt-ps-col-right { grid-column: 1; margin-top: 0; }
