}
.lp-hero-recog-label { font-size: 14px; font-weight: 500; color: rgba(255, 255, 255, 0.75); white-space: nowrap; }
.lp-hero-recog-logos { display: flex; flex-wrap: wrap; align-items: center; gap: 64px; }
.lp-hero-recog-logo { display: flex; align-items: center; }
.lp-hero-recog-logo img { max-height: 36px; width: auto; display: block; filter: grayscale(1) brightness(2.2); opacity: 0.85; }

@media (max-width: 1100px) {
  .dt-hero-grid-layout.lp-hero-grid { max-width: 100%; grid-template-columns: minmax(0, 1fr); gap: 30px; padding-top: 45px; }
  .lp-hero .dt-hero-content { max-width: unset; }
  .lp-hero-form-card { max-width: 560px; margin-left: auto; margin-right: auto; }
  .lp-hero-recog { max-width: 90%; }
}

@media (max-width: 640px) {
  .dt-hero-grid-layout.lp-hero-grid { padding-top: 48px; padding-bottom: 40px; }
  .lp-hero-form-card { padding: 24px; }
