/* ── Header V2 — Landing Page nav (template-parts/header/nav-header-lp.php) ──
   Stripped nav for lp_hero pages: logo + phone + email, no menu. Deliberately
   self-contained (no shared classes with #hp-nav) so it doesn't inherit or
   fight the site's mega-menu CSS. */
.lp-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 900;
  background: transparent;
  border-bottom: 1px solid transparent;
  transition: background 0.25s ease, border-color 0.25s ease, backdrop-filter 0.25s ease;
}
/* Transparent + overlaying the hero photo at the top of the page (lp-hero-grid's
   own top padding clears it); lp-nav.js adds .is-scrolled once the user scrolls
   past the hero, switching it to the solid sticky bar. */
.lp-nav.is-scrolled {
  background: #05070b;
  border-bottom-color: rgba(236, 28, 36, 0.25);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.lp-nav-inner {
  max-width: 80%;
  margin: 0 auto;
  padding: 18px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.lp-nav-logo { display: flex; align-items: center; flex-shrink: 0; }
.lp-nav-logo img { display: block; width: 171px; height: 32px; }

.lp-nav-contact { display: flex; align-items: center; gap: 40px; }
.lp-nav-contact-item {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #fff;
  text-decoration: none;
}
.lp-nav-contact-ic {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid rgba(236, 28, 36, 0.5);
  color: var(--dt-red);
  flex-shrink: 0;
}
.lp-nav-contact-text { display: flex; flex-direction: column; line-height: 1.3; }
.lp-nav-contact-label { font-size: 12px; color: rgba(255, 255, 255, 0.6); }
.lp-nav-contact-value { font-size: 14px; font-weight: 600; color: #fff; }

@media (max-width: 900px) {
  .lp-nav-contact-label { display: none; }
  .lp-nav-contact { gap: 20px; }
}
@media (max-width: 640px) {
  .lp-nav-inner { max-width: 90%; padding: 14px 0; }
  .lp-nav-contact-value { font-size: 12px; }
  .lp-nav-contact-ic { width: 28px; height: 28px; }
}
@media (max-width: 480px) {
  /* Phone + email together no longer fit next to the logo at this width;
     keep phone (the primary tap-to-call CTA) and drop email. */
  .lp-nav-logo img { width: 130px; height: auto; }
  .lp-nav-contact-item[href^="mailto:"] { display: none; }
