/* -- Consultation Steps (consult_steps layout) -------------------------
   Three numbered step cards; the featured one renders taller and shows
   its description. Background art is a procedural blurred blob (layered
   radial-gradients on ::before, animated via transform) rather than a
   raster image, so it can drift continuously without a static crop.
   Sizing matches the approved Figma reference: 39px card corners, 69x73
   icon box with a 36px glyph, 75px numbers, 28/33px titles, 19px desc. */
.cst-head {
  display: flex;
  align-items: center;
  align-content: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: nowrap;
  flex-direction: row;
  width: 100% !important;
  max-width: 100%;
}

.cst-head-cta {
  flex: 0 0 auto;
  padding-top: 4px;
}

.cst-cards {
  margin-top: 48px;
  display: flex;
  align-items: center;
  gap: 24px;
	height : 600px
}

.cst-card {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  background: #fff;
  border: 1.5px solid rgba(168, 164, 164, 0.5);
  border-radius: 39px;
  overflow: hidden;
  min-height: 380px;
  padding: 10px;
}

.cst-card.is-featured {
  min-height: 480px;
  z-index: 1;
}


@keyframes cstBlobMove {
  0%   { transform: translate(0, 0) scale(1); filter: blur(55px) saturate(1.15) hue-rotate(0deg); }
  50%  { transform: translate(6%, -8%) scale(1.18); filter: blur(55px) saturate(1.35) hue-rotate(20deg); }
  100% { transform: translate(0, 0) scale(1); filter: blur(55px) saturate(1.15) hue-rotate(0deg); }
}

/* Second, independent motion layered on top of cstBlobMove (different period,
   so the two never sync up) — drifts each radial-gradient layer's own
   position separately, so the blobs read as two overlapping shapes moving
   through each other rather than one shape moving as a rigid block. */
@keyframes cstBlobDrift {
  0%   { background-position: 0% 0%, 0% 0%, 0% 0%; }
  33%  { background-position: 18% -14%, -16% 10%, 10% 14%; }
  66%  { background-position: -10% 12%, 14% -10%, -14% -8%; }
  100% { background-position: 0% 0%, 0% 0%, 0% 0%; }
}

.cst-card-art {
  position: relative;
  height: 380px;
  flex: 0 0 auto;
  overflow: hidden;
  border-radius: 29px 29px 0 0;
  background: #fff;
}

.cst-card-body {
  flex: 1 1 auto;
  border-radius: 0 0 29px 29px;
  background: #fff;
}

.cst-card-art::before {
  content: "";
  position: absolute;
  inset: -45%;
  background-image:
    /* Purple */
    radial-gradient(
      ellipse 65% 60% at 52% 30%,
      rgba(150, 60, 220, 0.45) 0%,
      #963cdc 30%,
      rgba(255, 255, 255, 0) 68%
    ),

    /* Pink */
    radial-gradient(
      ellipse 55% 55% at 26% 58%,
      rgba(255, 80, 170, 0.4) 0%,
      rgba(255, 140, 200, 0.2) 35%,
      rgba(255, 255, 255, 0) 65%
    ),

    /* Red */
    radial-gradient(
      ellipse 50% 45% at 70% 75%,
      rgba(236, 28, 36, 0.5) 0%,
      rgba(220, 30, 70, 0.3) 35%,
      rgba(255, 255, 255, 0) 70%
    );
  background-position: 0% 0%, 0% 0%, 0% 0%;
  filter: blur(55px) saturate(1.1);
  will-change: transform, background-position;
}

.cst-card:nth-child(2) .cst-card-art::before {
  background-image:
    /* Purple */
    radial-gradient(
      ellipse 65% 60% at 52% 30%,
      rgba(150, 60, 220, 0.45) 0%,
      #963cdc 30%,
      rgba(255, 255, 255, 0) 68%
    ),

    /* Pink */
    radial-gradient(
      ellipse 55% 55% at 26% 58%,
      rgba(255, 80, 170, 0.4) 0%,
      rgba(255, 140, 200, 0.2) 35%,
      rgba(255, 255, 255, 0) 65%
    ),

    /* Red */
    radial-gradient(
      ellipse 50% 45% at 70% 75%,
      rgba(236, 28, 36, 0.5) 0%,
      rgba(220, 30, 70, 0.3) 35%,
      rgba(255, 255, 255, 0) 70%
    );
}

.cst-card:nth-child(3) .cst-card-art::before {
background-image:
    /* Purple */
    radial-gradient(
      ellipse 65% 60% at 52% 30%,
      rgba(150, 60, 220, 0.45) 0%,
      #963cdc 30%,
      rgba(255, 255, 255, 0) 68%
    ),

    /* Pink */
    radial-gradient(
      ellipse 55% 55% at 26% 58%,
      rgba(255, 80, 170, 0.4) 0%,
      rgba(255, 140, 200, 0.2) 35%,
      rgba(255, 255, 255, 0) 65%
    ),

    /* Red */
    radial-gradient(
      ellipse 50% 45% at 70% 75%,
      rgba(236, 28, 36, 0.5) 0%,
      rgba(220, 30, 70, 0.3) 35%,
      rgba(255, 255, 255, 0) 70%
    );
}

@media (prefers-reduced-motion: no-preference) {
  .cst-card-art::before {
    animation: cstBlobMove 3s ease-in-out infinite, cstBlobDrift 7s ease-in-out infinite;
  }
}

.cst-card-art::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(to top, #fff 0%, rgba(255, 255, 255, 0) 20%),
    radial-gradient(circle at 0% 0%, #fff 0%, rgba(255, 255, 255, 0) 45%),
    radial-gradient(circle at 100% 0%, #fff 0%, rgba(255, 255, 255, 0) 45%),
    radial-gradient(circle at 0% 100%, #fff 0%, rgba(255, 255, 255, 0) 45%),
    radial-gradient(circle at 100% 100%, #fff 0%, rgba(255, 255, 255, 0) 50%);
  pointer-events: none;
}

.cst-card-num {
  position: absolute;
  z-index: 1;
  right: 20px;
  bottom: 10px;
  font-family: 'Outfit', system-ui, sans-serif;
  font-size: 75px;
  font-weight: 500;
  line-height: 1;
  color: rgba(255, 194, 196, 0.63);
  background: linear-gradient(135deg, rgba(255, 20, 147, 0.5), rgba(255, 182, 193, 0.4));
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

